window.WORD_AI_EXAMPLE_CHUNK = {"entries":{"reproach":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"责备"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"耻辱"}],"examples":[{"sentence":"While the reproach from her mentor stung, it ultimately guided her toward a more rigorous research methodology.","translation":"虽然导师的责备让她难受，但最终引导她采用了更严谨的研究方法。","targetForm":"reproach","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the manager's reproach was delivered privately, it prompted the team to revise their strategy before the deadline.","translation":"尽管经理的责备是私下进行的，但它促使团队在截止日期前修改了策略。","targetForm":"reproach","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The company's failure to address safety concerns brought reproach upon its leadership, which damaged investor confidence.","translation":"公司未能解决安全问题给其领导层带来了耻辱，这损害了投资者的信心。","targetForm":"reproach","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Through his reproach of the outdated policy, the activist inspired a movement that demanded legislative reform.","translation":"通过对过时政策的责备，这位活动家激发了一场要求立法改革的运动。","targetForm":"reproach","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The scientist faced widespread reproach because he had manipulated data to support his hypothesis.","translation":"这位科学家面临广泛的责备，因为他篡改数据以支持自己的假设。","targetForm":"reproach","senseId":"source-n-1","sourceSenseId":"n-1"}]},"reasonable":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"合理的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"适当的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"明理的"}],"examples":[{"sentence":"The committee reached a reasonable decision after comparing the cost of repairs with the value of preserving the building.","translation":"委员会比较维修成本与保护建筑的价值后，作出了合理决定。","targetForm":"reasonable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the timetable was demanding, the students considered it reasonable because the deadlines were announced early.","translation":"尽管时间表要求很高，学生仍认为它合理，因为截止日期很早就公布了。","targetForm":"reasonable","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The mediator asked both sides to make reasonable requests that the other party could realistically consider.","translation":"调解员要求双方提出对方能够现实考虑的合理要求。","targetForm":"reasonable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because she was reasonable about the delay, the team could explain the problem without the discussion becoming hostile.","translation":"由于她对延误很通情达理，团队得以解释问题而不使讨论变得敌对。","targetForm":"reasonable","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"A reasonable argument acknowledges evidence that challenges its conclusion rather than ignoring inconvenient facts.","translation":"合理的论证会承认证据对结论的挑战，而不是忽视令人不便的事实。","targetForm":"reasonable","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"retail":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"零售"}],"examples":[{"sentence":"For northern Europeans, two prospects raise particular concern: risk sharing (for example, in underwriting retail bank deposits) and a eurozone budget.","translation":"对北欧来说，两个前景引起了特别关注：风险分担（比如兜底零售银行存款）和欧元区预算。","targetForm":"retail","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Organic kale is hand picked, washed and packed on site at Sprouting Farms, West Virginia, for retail and wholesale.","translation":"有机羽衣甘蓝在西维吉尼亚州的 Sprouting Farms 现场手工采摘、清洗和包装，提供零售和批发。","targetForm":"retail","senseId":"source-n-1","sourceSenseId":"n-1"}]},"relief":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"安慰"}],"examples":[{"sentence":"His humor charmingly eased the embarrassing atmosphere at dinner time and made me breathe a sigh of relief.","translation":"他的幽默巧妙地缓解了晚餐时尴尬的气氛，让我松了一口气。","targetForm":"relief","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The next morning, to our great relief, he returned home safe and sound.","translation":"第二天早上，他就平安无事的回来了，我们都大大的松了一口气。","targetForm":"relief","senseId":"source-n-4","sourceSenseId":"n-4"}]},"region":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"地区"}],"examples":[{"sentence":"Turkey is currently confronting the limits of its possibilities, while the EU finds that it can do very little in this region without Turkey.","translation":"此外，在欧洲的南方近邻，即地中海地区，新风险正在北非和撒哈拉地区迅猛崛起，包括基地组织对马里北部的威胁。","targetForm":"region","senseId":"source-n-3","sourceSenseId":"n-3"}]},"reassure":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使...安心"}],"examples":[{"sentence":"Her steady voice reassured the child that the noise outside would soon disappear.","translation":"她平稳的声音让孩子安心，告诉他外面的噪声很快就会消失。","targetForm":"reassured","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although the first test failed, the engineer reassured the team that the design could be improved.","translation":"尽管第一次测试失败了，工程师仍让团队相信这个设计可以改进。","targetForm":"reassured","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"To reassure investors, the company published a transparent statement explaining its recovery plan.","translation":"为了让投资者安心，这家公司公布了一份透明声明，说明其复苏计划。","targetForm":"reassure","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The doctor's careful explanation reassured the family because it answered their most urgent questions.","translation":"医生细致的解释让家人安心，因为它回答了他们最迫切的问题。","targetForm":"reassured","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Regular updates from the leadership can reassure employees during a period of organisational change.","translation":"在组织变革期间，领导层定期发布进展可以使员工安心。","targetForm":"reassure","senseId":"source-v-1","sourceSenseId":"v-1"}]},"reservation":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"保留"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"预定"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"保留地"}],"examples":[{"sentence":"She accepted the job offer without reservation, eager to start her new career in the city.","translation":"她毫无保留地接受了这份工作邀请，渴望在城市开始新的职业生涯。","targetForm":"reservation","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The committee expressed strong reservations about the proposed budget cuts for education.","translation":"委员会对拟议的教育预算削减表示了强烈的保留意见。","targetForm":"reservations","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"We made a dinner reservation at the renowned restaurant weeks in advance to secure a table.","translation":"我们提前几周就在那家知名餐厅预订了晚餐，以确保有座位。","targetForm":"reservation","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The hotel confirmed our reservation via email, including details about the check-in time.","translation":"酒店通过电子邮件确认了我们的预订，包括入住时间的详细信息。","targetForm":"reservation","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The indigenous community has lived on the reservation for generations, preserving their cultural heritage.","translation":"原住民社区世代居住在保留地上，保护着他们的文化遗产。","targetForm":"reservation","senseId":"source-n-4","sourceSenseId":"n-4"}]},"reply":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"答复"}],"examples":[{"sentence":"I'm extremely embarrassed that it has taken so long to reply.","translation":"我过了这么久才回信，真的十分不好意思。","targetForm":"reply","senseId":"source-n-1","sourceSenseId":"n-1"}]},"reward":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"报酬"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"赏金"}],"examples":[{"sentence":"With private rewards so markedly different from social returns, it is no surprise that the pursuit of self-interest (greed) led to such socially destructive consequences.","translation":"此外，对于那些真正在做银行被认为应该做的事情即贷款以及评估信用的那些银行的帮助非常之少。","targetForm":"rewards","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A reward will be paid to anyone who brings back the money that he lost.","translation":"凡能将他遗失的钱寻回者可得到酬金。","targetForm":"reward","senseId":"source-n-3","sourceSenseId":"n-3"}]},"redundant":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"多余的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"[医] 过多的","contextReviewed":true}],"examples":[{"sentence":"The editor removed several redundant phrases from the manuscript to improve its clarity and conciseness.","translation":"编辑从手稿中删除了几个冗余的短语，以提高其清晰度和简洁性。","targetForm":"redundant","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"After the merger, many positions became redundant, leading to a series of layoffs across the company.","translation":"合并后，许多职位变得多余，导致公司内部进行了一系列裁员。","targetForm":"redundant","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The report contained redundant information that had already been covered in the previous section.","translation":"报告中包含了冗余信息，这些信息在前一节中已经涵盖。","targetForm":"redundant","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"In the digital age, physical media like CDs and DVDs are increasingly seen as redundant.","translation":"在数字时代，像CD和DVD这样的物理媒介越来越被视为多余。","targetForm":"redundant","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The patient was diagnosed with a redundant colon, which required surgical intervention to alleviate discomfort.","translation":"患者被诊断出结肠过长，需要手术干预以缓解不适。","targetForm":"redundant","senseId":"source-adj-4","sourceSenseId":"adj-4"}]},"report":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"报告"}],"examples":[{"sentence":"This column draws on a Bruegel report co-authored with André Sapir and Guntram Wolff.","translation":"本专栏改编自与André Sapir和Guntram Wolff合作的Bruegel报告。","targetForm":"report","senseId":"source-n-1","sourceSenseId":"n-1"}]},"remain":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"保持"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"剩余"}],"examples":[{"sentence":"The museum remains open until eight o'clock on Fridays.","translation":"博物馆周五一直开放到晚上八点。","targetForm":"remains","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Only two questions remain after the group finishes the report.","translation":"小组完成报告后，只剩下两个问题。","targetForm":"remain","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Please remain seated until the train has come to a complete stop.","translation":"请保持坐姿，直到列车完全停稳。","targetForm":"remain","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Despite the repairs, the bridge remains closed to heavy vehicles.","translation":"尽管已经维修，这座桥仍不对重型车辆开放。","targetForm":"remains","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Several old trees remained after the storm damaged the park.","translation":"暴风雨损坏公园后，仍有几棵老树留了下来。","targetForm":"remained","senseId":"source-v-3","sourceSenseId":"v-3"}]},"repetition":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"重复"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"背诵"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"循环"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"复制品"},{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"[机] 重复","contextReviewed":true}],"examples":[{"sentence":"The constant repetition of the same argument made the discussion tedious and unproductive.","translation":"不断重复同样的论点使讨论变得乏味且毫无成效。","targetForm":"repetition","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Her flawless repetition of the complex poem impressed the entire audience at the recital.","translation":"她完美地背诵了那首复杂的诗，给朗诵会上的所有观众留下了深刻印象。","targetForm":"repetition","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The repetition of the seasons is a fundamental cycle that governs agricultural practices worldwide.","translation":"季节的循环是支配全球农业实践的基本周期。","targetForm":"repetition","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The museum displayed a repetition of the ancient vase, as the original was too fragile to exhibit.","translation":"博物馆展出了那个古代花瓶的复制品，因为原件太脆弱而无法展出。","targetForm":"repetition","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The engineer explained that the machine's repetition of the same motion ensures consistent product quality.","translation":"工程师解释说，机器重复相同的动作确保了产品质量的一致性。","targetForm":"repetition","senseId":"source-n-6","sourceSenseId":"n-6"}]},"religion":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"宗教"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"信仰"}],"examples":[{"sentence":"Although religion often provides moral guidance, its place in public policy remains a contested question.","translation":"尽管宗教常提供道德指引，它在公共政策中的位置仍是一个有争议的问题。","targetForm":"religion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because religion influences cultural traditions, it shapes festivals and rituals that strengthen community ties.","translation":"由于宗教影响文化传统，它塑造了能加强社区联系的节日和仪式。","targetForm":"religion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While some argue that religion hinders scientific progress, others cite religious institutions that have supported research.","translation":"虽然有人认为宗教阻碍科学进步，另一些人则列举支持研究的宗教机构作为反例。","targetForm":"religion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The academic study of religion combines history, anthropology, and philosophy in order to examine belief in context.","translation":"宗教的学术研究结合历史学、人类学和哲学，以便在语境中考察信仰。","targetForm":"religion","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In pluralistic societies, freedom of religion protects citizens who wish to practise their faith without discrimination.","translation":"在多元社会中，宗教自由保护希望不受歧视地实践其信仰的公民。","targetForm":"religion","senseId":"source-n-2","sourceSenseId":"n-2"}]},"relationship":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"关系"}],"examples":[{"sentence":"So here we are with yet another twist in the never-ending saga of our love/hate relationship with capital controls.","translation":"在这里，我们还面临另一场从未结束的与资本管制的爱恨纠结。","targetForm":"relationship","senseId":"source-n-1","sourceSenseId":"n-1"}]},"reservoir":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"水库"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"贮水池"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"贮藏处"}],"examples":[{"sentence":"Because the reservoir was built without adequate environmental assessment, it disrupted the migration routes of several endangered fish species.","translation":"由于水库在建设时没有进行充分的环境评估，它扰乱了几种濒危鱼类的迁徙路线。","targetForm":"reservoir","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Although the reservoir was intended to boost agricultural productivity, its construction led to the displacement of thousands of rural families.","translation":"尽管该水库旨在提高农业生产力，但其建设导致数千农村家庭流离失所。","targetForm":"reservoir","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Wetlands act as a natural reservoir for floodwaters, which helps to protect downstream communities from catastrophic inundation during heavy rains.","translation":"湿地作为洪水的天然蓄水池，有助于保护下游社区在暴雨期间免受灾难性淹没。","targetForm":"reservoir","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The human gut microbiome is a vast reservoir of genetic diversity, which plays a crucial role in digestion and immune function.","translation":"人类肠道微生物组是遗传多样性的巨大储存库，在消化和免疫功能中起着至关重要的作用。","targetForm":"reservoir","senseId":"source-n-2","sourceSenseId":"n-2"}]},"response":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"反应"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"响应"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"回答"}],"examples":[{"sentence":"Although the initial response to the policy was negative, later adjustments won broader public approval.","translation":"尽管公众最初对该政策反应消极，后续调整还是赢得了更广泛的认可。","targetForm":"response","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The company's rapid response to the data breach, which included notifying affected users, helped restore trust.","translation":"公司对数据泄露的迅速回应包括通知受影响用户，这有助于恢复信任。","targetForm":"response","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Because the government's response to the downturn was timely, the recession proved shorter than many economists expected.","translation":"由于政府对经济下滑的应对及时，衰退期比许多经济学家预期的更短。","targetForm":"response","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"When students receive constructive feedback, their response can lead to meaningful improvements in later work.","translation":"当学生收到建设性反馈时，他们的回应能够促成后续作业的实质性改进。","targetForm":"response","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The international community's coordinated response ensured that humanitarian aid reached the affected areas efficiently.","translation":"国际社会的协调响应确保人道援助高效送达受影响地区。","targetForm":"response","senseId":"source-n-3","sourceSenseId":"n-3"}]},"reverse":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"倒退"}],"examples":[{"sentence":"If we want to reverse these trends and maximize innovation output, we need more mechanisms for funding the commercialization of smart ideas.","translation":"如果想扭转上述趋势并最大限度地提高创新产出，我们需要更多机制来为聪明的理念提供商业化资助。","targetForm":"reverse","senseId":"source-n-3","sourceSenseId":"n-3"}]},"renaissance":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"复兴"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"文艺复兴"}],"examples":[{"sentence":"The renaissance of traditional crafts, which had nearly vanished during industrialization, now provides sustainable livelihoods for rural communities.","translation":"传统手工艺的复兴，在工业化期间几乎消失，现在为农村社区提供了可持续的生计。","targetForm":"renaissance","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"While some scholars debate its exact boundaries, the Harlem Renaissance remains a pivotal moment in African American cultural history.","translation":"虽然一些学者争论其确切界限，哈莱姆文艺复兴仍然是非裔美国人文化史上的一个关键时刻。","targetForm":"renaissance","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"A renaissance in scientific inquiry during the 17th century laid the groundwork for modern physics, thereby transforming our understanding of the universe.","translation":"17世纪科学探究的复兴为现代物理学奠定了基础，从而改变了我们对宇宙的理解。","targetForm":"renaissance","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the term originally referred to a historical period, a renaissance of interest in classical music has recently emerged among young audiences.","translation":"尽管这个词最初指一个历史时期，但最近年轻观众对古典音乐的兴趣出现了复兴。","targetForm":"renaissance","senseId":"source-n-2","sourceSenseId":"n-2"}]},"recent":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"最近的"}],"examples":[{"sentence":"At least two recent examples illustrate the potentially devastating effects of collective mechanisms for protecting savers despite a joint banking regulator.","translation":"至少有两个最近的例子可以说明保护储户的集体机制如何导致灾难性后果，哪怕存在联合银行监管当局。","targetForm":"recent","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"relate":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"有关"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"使互相关联"}],"examples":[{"sentence":"It is unclear why these trends are occurring, although the impact of new technologies and related network effects is certainly part of the reason.","translation":"这些趋势为何发生尚不清楚，但新科技和相关网络效应显然是部分原因。","targetForm":"related","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Britain’s pro-European progressive forces could still snatch victory from the jaws of defeat for three related reasons.","translation":"英国的亲欧进步力量仍有可能出奇制胜，有三个互相关联的原因。","targetForm":"related","senseId":"source-v-3","sourceSenseId":"v-3"}]},"restless":{"senseGroups":[{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"不安的；焦躁的；不宁的","contextReviewed":true},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"休息不充分的"}],"examples":[{"sentence":"Although she was exhausted, restless anxiety kept her awake before the important examination.","translation":"尽管她筋疲力尽，焦躁不安仍使她在重要考试前无法入睡。","targetForm":"restless","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"When employees lack meaningful challenges, they may become restless and gradually disengage from their work.","translation":"当员工缺少有意义的挑战时，他们可能变得焦躁，并逐渐脱离工作投入。","targetForm":"restless","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"The restless crowd remained near the entrance until the organiser announced a new starting time.","translation":"焦躁的人群一直停留在入口附近，直到组织者宣布新的开始时间。","targetForm":"restless","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"Because the novel's restless protagonist cannot settle in one place, the story moves across several countries.","translation":"由于小说中不安分的主人公无法在一地安顿，故事辗转于多个国家。","targetForm":"restless","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"A restless night can impair concentration the next day, which is why students need a stable routine.","translation":"辗转难眠的一夜会损害第二天的专注力，因此学生需要稳定的作息。","targetForm":"restless","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"real":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"真的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"实在的"}],"examples":[{"sentence":"Europe deserves to prove that it is a real community, one diverse, democratic, spiritual, free, and prosperous.","translation":"欧洲应该证明自己是一个真正的社会，一个多元、民主、高尚、自由和繁荣的社会。","targetForm":"real","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The risk that imperial hubris accelerates, rather than stems, Islamist terror is all too real – yet again.","translation":"帝国傲慢可能再一次助长而不是遏制伊斯兰恐怖主义，这一风险是实实在在的。","targetForm":"real","senseId":"source-adj-4","sourceSenseId":"adj-4"}]},"request":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"请求"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"申请书"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"请求"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"要求"}],"examples":[{"sentence":"Although the manager initially denied the request, she reconsidered it after reviewing the revised budget.","translation":"尽管经理最初拒绝了该请求，她在审查修订后的预算后重新考虑了。","targetForm":"request","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The committee will approve the funding request only if the applicant provides a detailed timetable.","translation":"委员会只有在申请人提供详细时间表后才会批准经费申请。","targetForm":"request","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Because the request for more staff was well supported by evidence, the board approved it immediately.","translation":"由于增加员工的请求有充分证据支持，董事会立即批准了它。","targetForm":"request","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When requesting a visa extension, applicants must include a valid passport and a recent photograph.","translation":"申请签证延期时，申请人必须附上有效护照和近期照片。","targetForm":"requesting","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The customer requested a refund after the product failed, which led the company to review the complaint.","translation":"产品发生故障后，顾客要求退款，公司因此审查了该投诉。","targetForm":"requested","senseId":"source-v-2","sourceSenseId":"v-2"}]},"remnant":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"遗迹"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"剩余"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"零料"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"残余的"}],"examples":[{"sentence":"The archaeologists discovered a remnant of an ancient wall that once surrounded the medieval city.","translation":"考古学家发现了一段曾经环绕中世纪城市的古城墙遗迹。","targetForm":"remnant","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"After the fire, only a few charred remnants of the library's priceless manuscript collection could be salvaged.","translation":"火灾之后，图书馆珍贵的藏书手稿只剩下一些烧焦的残余部分能够被抢救出来。","targetForm":"remnants","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The tailor used the remnant of the silk fabric to craft a delicate scarf for her daughter.","translation":"裁缝用剩余的丝绸面料为女儿制作了一条精致的围巾。","targetForm":"remnant","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The remnant vegetation on the hillside provides a crucial habitat for several endangered bird species.","translation":"山坡上残余的植被为几种濒危鸟类提供了至关重要的栖息地。","targetForm":"remnant","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Scientists are studying the remnant magnetic fields in ancient rocks to understand the Earth's geological history.","translation":"科学家正在研究古代岩石中残余的磁场，以了解地球的地质历史。","targetForm":"remnant","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"resistance":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"反抗"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"抵抗力"},{"id":"source-n-8","partOfSpeech":"n.","sourceSenseIds":["n-8"],"sense":"抗药性","contextReviewed":true}],"examples":[{"sentence":"Widespread resistance to the tax policy resulted from poor communication, which the government later addressed through public forums.","translation":"对税收政策的广泛抵制源于沟通不充分，政府后来通过公开论坛加以解决。","targetForm":"resistance","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Regular exercise builds endurance and strengthens the body's resistance to common infections.","translation":"规律锻炼能增强耐力并提高身体对常见感染的抵抗力。","targetForm":"resistance","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The material's resistance to heat makes it suitable for components that must withstand extreme temperatures.","translation":"这种材料的耐热性使它适用于必须承受极端温度的部件。","targetForm":"resistance","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because employees feared uncertainty, internal resistance to change became the hardest part of the restructuring.","translation":"由于员工害怕不确定性，内部对变革的阻力成为重组中最困难的部分。","targetForm":"resistance","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Prolonged antibiotic use can create bacterial resistance, making standard treatment ineffective unless new drugs are developed.","translation":"长期使用抗生素可能产生细菌耐药性，使标准治疗失效，除非开发新药。","targetForm":"resistance","senseId":"source-n-8","sourceSenseId":"n-8"}]},"remains":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"残余"}],"examples":[{"sentence":"And yet, for all the woe, a resolution remains possible; to achieve it, five steps must be taken without delay.","translation":"但尽管局势如此痛苦，仍然保留着和平解决的生机；要想实现这个目标，必须立即实行五步走政策。","targetForm":"remains","senseId":"source-n-3","sourceSenseId":"n-3"}]},"rear":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"后面"}],"examples":[{"sentence":"Because the rear entrance is less congested, employees prefer to use it when arriving during peak hours.","translation":"由于后门入口不那么拥挤，员工在高峰时段到达时更喜欢使用它。","targetForm":"rear","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While the front facade was meticulously restored, the rear of the historic mansion still requires significant renovation.","translation":"虽然正面外墙被精心修复，但这座历史宅邸的后部仍需要大规模翻新。","targetForm":"rear","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the rear of the building appears unremarkable, it houses a state-of-the-art laboratory that drives the company's innovation.","translation":"尽管建筑物的后部看起来不起眼，但它容纳了一个推动公司创新的尖端实验室。","targetForm":"rear","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"To ensure privacy, the architect designed the master bedroom at the rear of the house, away from the street noise.","translation":"为了确保隐私，建筑师将主卧室设计在房屋后部，远离街道噪音。","targetForm":"rear","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The garden at the rear of the property, which features a variety of native plants, provides a tranquil space for relaxation.","translation":"房屋后部的花园种植了多种本地植物，提供了一个宁静的休闲空间。","targetForm":"rear","senseId":"source-n-1","sourceSenseId":"n-1"}]},"render":{"senseGroups":[{"id":"source-v-10","partOfSpeech":"v.","sourceSenseIds":["v-10"],"sense":"致使"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"给于"},{"id":"source-v-8","partOfSpeech":"v.","sourceSenseIds":["v-8"],"sense":"表示"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"提出"}],"examples":[{"sentence":"Prolonged exposure to moisture can render electronic devices inoperable, so manufacturers recommend dry storage.","translation":"长时间暴露在潮湿环境中会使电子设备无法运行，因此制造商建议干燥存放。","targetForm":"render","senseId":"source-v-10","sourceSenseId":"v-10"},{"sentence":"The charity chose to render immediate aid to flood victims, thereby providing food, shelter, and medical supplies.","translation":"该慈善机构选择立即向洪水受灾者提供援助，从而提供食物、住所和医疗物资。","targetForm":"render","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"To render the legal document understandable, the lawyer summarised it in plain language without jargon.","translation":"为了使法律文件易于理解，律师用没有术语的通俗语言进行了概述。","targetForm":"render","senseId":"source-v-10","sourceSenseId":"v-10"},{"sentence":"The artist rendered the sunset with vivid brushstrokes that captured its brief changing light.","translation":"艺术家用生动笔触表现日落，捕捉了它短暂变化的光线。","targetForm":"rendered","senseId":"source-v-8","sourceSenseId":"v-8"},{"sentence":"When the committee could not agree, the chair was required to render a final judgment based on the evidence.","translation":"委员会无法达成一致时，主席必须根据证据作出最终裁决。","targetForm":"render","senseId":"source-v-5","sourceSenseId":"v-5"}]},"reform":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"改革"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"改革"}],"examples":[{"sentence":"The agricultural reform modernised farming methods, which increased crop yields and improved rural livelihoods.","translation":"农业改革使耕作方法现代化，提高了作物产量并改善了农村生计。","targetForm":"reform","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Educational reform can make classrooms more interactive when technology is used to support meaningful learning.","translation":"当技术被用于支持有意义的学习时，教育改革能够让课堂更具互动性。","targetForm":"reform","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the tax reform faced opposition, economists argued that it could reduce inequality and support growth.","translation":"尽管税收改革遭到反对，经济学家认为它能够减少不平等并支持增长。","targetForm":"reform","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The company reformed its internal rules after the scandal in order to restore public trust.","translation":"丑闻发生后，公司改革了内部规则，以恢复公众信任。","targetForm":"reformed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because healthcare reform expanded insurance coverage, more patients received earlier diagnoses and better long-term care.","translation":"由于医疗改革扩大了保险覆盖，更多患者获得了更早诊断和更好的长期照护。","targetForm":"reform","senseId":"source-n-1","sourceSenseId":"n-1"}]},"relish":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"滋味"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"风味"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"喜欢"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"玩味"}],"examples":[{"sentence":"She ate the homemade pickle with evident relish, savoring its tangy and spicy flavor.","translation":"她津津有味地吃着自制的泡菜，品味着它酸辣的味道。","targetForm":"relish","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The chef added a dollop of tomato relish to the grilled fish, enhancing its overall taste.","translation":"厨师在烤鱼上加了一勺番茄调味酱，提升了整体的味道。","targetForm":"relish","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"He relishes the opportunity to debate complex philosophical issues with his colleagues.","translation":"他喜欢有机会与同事辩论复杂的哲学问题。","targetForm":"relishes","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The children relished every moment of the outdoor adventure, from hiking to roasting marshmallows.","translation":"孩子们尽情享受户外探险的每一刻，从徒步旅行到烤棉花糖。","targetForm":"relished","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"As a connoisseur, she relishes the subtle differences between various vintages of fine wine.","translation":"作为一名鉴赏家，她喜欢品味不同年份美酒之间的细微差别。","targetForm":"relishes","senseId":"source-v-3","sourceSenseId":"v-3"}]},"relation":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"关系"}],"examples":[{"sentence":"The Summit of the Americas thus serves as a bellwether of United States-Latin American relations, even if it fails to accomplish much of significance.","translation":"于是，美洲峰会就成了美国-拉美关系的风向标，尽管这个风向标有时并不怎么灵验。","targetForm":"relations","senseId":"source-n-1","sourceSenseId":"n-1"}]},"refute":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"驳斥"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"反驳"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"驳倒"}],"examples":[{"sentence":"Although the early findings seemed conclusive, peer review helped experts refute weaknesses in the method.","translation":"尽管早期发现看似确凿，同行评审仍帮助专家驳斥方法中的弱点。","targetForm":"refute","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"To refute a common misconception, the scientist cited evidence from several independent studies.","translation":"为反驳常见误解，这位科学家引用了多项独立研究的证据。","targetForm":"refute","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the claim could not be refuted by the available evidence, the committee requested further investigation.","translation":"由于现有证据无法驳倒该主张，委员会要求进一步调查。","targetForm":"refuted","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The professor asked students to refute theories with evidence, thereby developing critical thinking.","translation":"教授要求学生用证据驳斥理论，从而培养批判性思维。","targetForm":"refute","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"While emotional appeals are tempting, verified data are more persuasive when we refute an opposing view.","translation":"尽管情感诉求很诱人，用可验证数据反驳相反观点更有说服力。","targetForm":"refute","senseId":"source-v-1","sourceSenseId":"v-1"}]},"rejoice":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"欣喜"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"高兴"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"庆祝"}],"examples":[{"sentence":"The entire nation rejoiced when the peace treaty was finally signed after decades of conflict.","translation":"当和平条约在数十年冲突后最终签署时，整个国家都欢欣鼓舞。","targetForm":"rejoiced","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"We rejoice in the success of our colleagues, recognizing that their achievements benefit the whole team.","translation":"我们为同事的成功感到欣喜，认识到他们的成就惠及整个团队。","targetForm":"rejoice","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The community rejoices at the news that the local library will receive substantial funding for renovations.","translation":"社区听到当地图书馆将获得大量翻新资金的消息而感到高兴。","targetForm":"rejoices","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"They are rejoicing over the birth of their first child, a moment of pure joy for the family.","translation":"他们正在庆祝第一个孩子的诞生，这对家庭来说是一个纯粹喜悦的时刻。","targetForm":"rejoicing","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The festival is a time when people come together to rejoice and give thanks for the harvest.","translation":"这个节日是人们聚集在一起庆祝并感恩丰收的时刻。","targetForm":"rejoice","senseId":"source-v-4","sourceSenseId":"v-4"}]},"reckless":{"senseGroups":[{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"鲁莽的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"不顾后果的"},{"id":"source-adj-5","partOfSpeech":"adj.","sourceSenseIds":["adj-5"],"sense":"（法律）不注意的","contextReviewed":true}],"examples":[{"sentence":"The reckless decision to publish unverified claims damaged the newspaper's credibility long after the story was withdrawn.","translation":"未经核实便发表说法的鲁莽决定，在报道撤下很久后仍损害了这家报纸的信誉。","targetForm":"reckless","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"By expanding overseas without a cash reserve, the firm was reckless with funds that employees depended on for their salaries.","translation":"公司在没有现金储备的情况下向海外扩张，对员工赖以领取工资的资金使用得很不顾后果。","targetForm":"reckless","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"Although the driver apologized, the court concluded that his reckless conduct had created an avoidable danger.","translation":"尽管司机道了歉，法院仍认定他的鲁莽行为造成了本可避免的危险。","targetForm":"reckless","senseId":"source-adj-5","sourceSenseId":"adj-5"},{"sentence":"Reckless spending may feel harmless at first, yet it can turn a temporary setback into a lasting financial burden.","translation":"鲁莽消费起初或许看似无害，却可能把暂时的挫折变成长久的经济负担。","targetForm":"reckless","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"Even during a crisis, leaders should avoid reckless promises that they cannot realistically keep.","translation":"即使在危机期间，领导者也应避免作出自己实际上无法兑现的轻率承诺。","targetForm":"reckless","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"resolute":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"坚决的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"刚毅的"}],"examples":[{"sentence":"Although the team faced setbacks, its resolute commitment kept members working toward the goal.","translation":"尽管团队遭遇挫折，坚定的承诺仍使成员朝目标努力。","targetForm":"resolute","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Because the leader was resolute about cutting unnecessary costs, the company survived the downturn.","translation":"由于领导在削减不必要成本上态度坚决，公司挺过了经济低迷。","targetForm":"resolute","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"A resolute commitment to environmental protection is essential if societies are to reduce long-term harm.","translation":"如果社会要减少长期损害，对环境保护的坚定承诺就至关重要。","targetForm":"resolute","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"When facing an ethical dilemma, a resolute person chooses integrity over personal advantage.","translation":"面对道德困境时，刚毅的人会选择诚信而非个人好处。","targetForm":"resolute","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"To make reform effective, governments need resolute action as well as transparent oversight.","translation":"为使改革有效，政府既需要坚决行动，也需要透明监督。","targetForm":"resolute","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"really":{"senseGroups":[{"id":"source-adv-2","partOfSpeech":"adv.","sourceSenseIds":["adv-2"],"sense":"真实地"}],"examples":[{"sentence":"The 8th of May always brings back memories of 1945, because for me the end of the war in Europe really was a zero hour.","translation":"五月八日总是将我们带回1945年的记忆中，因为对我而言欧洲战争的结束是真正的零时。","targetForm":"really","senseId":"source-adv-2","sourceSenseId":"adv-2"}]},"rent":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"房租"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"裂缝"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"租用"}],"examples":[{"sentence":"Although the rent is high, the apartment's location near the university attracts many students.","translation":"尽管房租很高，这间公寓靠近大学的位置仍吸引许多学生。","targetForm":"rent","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because the landlord delayed repairs, tenants asked for the rent to reflect the property's condition.","translation":"由于房东延迟维修，租户要求房租应反映房屋状况。","targetForm":"rent","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The sudden rise in rent created financial pressure for families who had not expected the change.","translation":"房租突然上涨给未预料到变化的家庭带来经济压力。","targetForm":"rent","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"When a rent appeared in the old canvas, the conservator repaired it before the exhibition opened.","translation":"旧帆布上出现裂口时，修复师在展览开幕前修补了它。","targetForm":"rent","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The company chose to rent more office space rather than purchase a new building.","translation":"公司选择租用更多办公空间，而不是购买新楼。","targetForm":"rent","senseId":"source-v-1","sourceSenseId":"v-1"}]},"retrospect":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"回顾"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"回溯"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"回顾"}],"examples":[{"sentence":"In retrospect, the committee's decision to delay the project proved remarkably prudent given the subsequent economic downturn.","translation":"事后看来，委员会推迟项目的决定在随后的经济衰退中显得非常明智。","targetForm":"retrospect","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The historian's retrospect of the medieval period revealed patterns of trade that had previously gone unnoticed.","translation":"这位历史学家对中世纪的回顾揭示了此前未被注意的贸易模式。","targetForm":"retrospect","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A careful retrospect of the negotiation process showed that both sides had made significant concessions early on.","translation":"对谈判过程的仔细回溯表明，双方在早期都做出了重大让步。","targetForm":"retrospect","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The philosopher often retrospected on his earlier works, finding new insights that he had missed in his youth.","translation":"这位哲学家经常回顾自己早期的作品，发现年轻时错过的新的见解。","targetForm":"retrospected","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"As the year drew to a close, she retrospected on the challenges she had overcome and the lessons she had learned.","translation":"随着这一年接近尾声，她回顾了自己所克服的挑战和学到的教训。","targetForm":"retrospected","senseId":"source-v-1","sourceSenseId":"v-1"}]},"removal":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"移动"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"移居"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"排除"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"切除"}],"examples":[{"sentence":"The careful removal of the archive to a climate-controlled building protected documents that had begun to decay.","translation":"把档案谨慎搬迁到恒温恒湿的建筑中，保护了已经开始老化的文件。","targetForm":"removal","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Her removal to a quieter town was intended to support her recovery after several exhausting months of treatment.","translation":"将她迁居到一座更安静的小镇，是为了帮助她在数月辛苦治疗后康复。","targetForm":"removal","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The removal of invasive fish requires patience because empty habitats can quickly be occupied again.","translation":"清除入侵鱼类需要耐心，因为空出的栖息地很快可能再次被占据。","targetForm":"removal","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Although the surgical removal of the tumour was successful, the patient still needed careful follow-up care.","translation":"尽管肿瘤的手术切除很成功，患者仍需要细致的后续护理。","targetForm":"removal","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"The committee debated the removal of a member who had repeatedly ignored the conflict-of-interest rules.","translation":"委员会讨论是否免去一名多次无视利益冲突规定的成员的资格。","targetForm":"removal","senseId":"source-n-4","sourceSenseId":"n-4"}]},"rein":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"缰绳"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"统治"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"支配"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"控制"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"以缰绳控制"}],"examples":[{"sentence":"The rider pulled sharply on the reins to avoid the fallen tree branch ahead.","translation":"骑手猛拉缰绳，以避开前方掉落的树枝。","targetForm":"reins","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"After the founder retired, the board assumed the reins of the company and implemented sweeping reforms.","translation":"创始人退休后，董事会接管了公司的统治权，并实施了全面改革。","targetForm":"reins","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The new manager gradually took the reins of the department, streamlining operations and boosting morale.","translation":"新经理逐渐掌握了部门的支配权，简化了流程并提升了士气。","targetForm":"reins","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Effective leaders must rein in impulsive decisions that could jeopardize long-term strategic goals.","translation":"有效的领导者必须控制住可能危及长期战略目标的冲动决策。","targetForm":"rein","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The experienced equestrian reined the horse gently to guide it through the narrow mountain pass.","translation":"经验丰富的骑手轻轻地以缰绳控制马匹，引导它穿过狭窄的山口。","targetForm":"reined","senseId":"source-v-2","sourceSenseId":"v-2"}]},"reel":{"senseGroups":[{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"蹒跚"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"一卷"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"卷轴"}],"examples":[{"sentence":"After the sudden policy shift, the entire industry was left to reel from the uncertainty that followed.","translation":"在政策突然转向之后，整个行业都因随之而来的不确定性而陷入混乱。","targetForm":"reel","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"Although the technician carefully threaded the reel through the projector, a minor misalignment still caused the image to flicker.","translation":"尽管技术人员小心翼翼地将片卷穿过放映机，但微小的错位仍然导致画面闪烁。","targetForm":"reel","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The fishing reel, which had been carefully maintained for decades, allowed the angler to land a surprisingly large catch.","translation":"那个被精心保养了几十年的渔轮，让垂钓者成功钓上了一条大得惊人的鱼。","targetForm":"reel","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When communities reel from the effects of rapid urbanization, planners must balance development with the preservation of green spaces.","translation":"当社区因快速城市化的影响而步履蹒跚时，规划者必须在发展与保护绿地之间取得平衡。","targetForm":"reel","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"Because the documentary footage arrived on a single film reel, the archivist had to digitize it before the material deteriorated.","translation":"由于纪录片素材是以单卷电影胶片的形式送达的，档案管理员必须在材料变质前将其数字化。","targetForm":"reel","senseId":"source-n-2","sourceSenseId":"n-2"}]},"repel":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"逐退"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"抗御"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"使厌恶"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"抵制"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"相互排斥"}],"examples":[{"sentence":"The fortress’s reinforced walls successfully repelled the invaders during the prolonged siege.","translation":"堡垒加固的城墙在漫长的围城战中成功逐退了入侵者。","targetForm":"repelled","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The fabric is treated with a special coating that repels water and resists stains effectively.","translation":"这种织物经过特殊涂层处理，能有效抗御水渍并抵抗污渍。","targetForm":"repels","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"His arrogant demeanor and dismissive remarks repelled even his most loyal supporters.","translation":"他傲慢的态度和轻蔑的言论甚至使最忠实的支持者都感到厌恶。","targetForm":"repelled","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The committee repelled the proposal because it lacked sufficient empirical evidence to justify the costs.","translation":"委员会抵制了该提案，因为它缺乏足够的实证证据来证明成本的合理性。","targetForm":"repelled","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"In physics, like magnetic poles repel each other while opposite poles attract with measurable force.","translation":"在物理学中，同极磁极相互排斥，而异极则相互吸引，产生可测量的力。","targetForm":"repel","senseId":"source-v-5","sourceSenseId":"v-5"}]},"recede":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"退却"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"减弱"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"向后退"}],"examples":[{"sentence":"As the floodwaters began to recede, the residents returned to assess the damage to their homes.","translation":"随着洪水开始退去，居民们返回评估他们房屋的受损情况。","targetForm":"recede","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The threat of a global pandemic receded after the widespread vaccination campaign proved highly effective.","translation":"在广泛疫苗接种运动证明非常有效后，全球大流行的威胁减弱了。","targetForm":"receded","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"His hairline had receded significantly over the past decade, a change he accepted with characteristic grace.","translation":"过去十年里，他的发际线明显后退了，他以一贯的优雅接受了这一变化。","targetForm":"receded","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The coastline is receding at an alarming rate due to erosion and rising sea levels.","translation":"由于侵蚀和海平面上升，海岸线正以惊人的速度后退。","targetForm":"receding","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Memories of the traumatic event gradually receded as she focused on building a new life.","translation":"随着她专注于建立新生活，创伤事件的记忆逐渐淡去。","targetForm":"receded","senseId":"source-v-5","sourceSenseId":"v-5"}]},"return":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"回来"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"返回"}],"examples":[{"sentence":"Third, we need to accept the fact that most of the refugees arriving in the EU will not return home.","translation":"第三，我们需要接受一个事实，即大部分到达欧盟的难民不会回去。","targetForm":"return","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"By fueling Japanese insecurity, US policy risks bringing about the very outcome – a return to militarism – that it aims to prevent.","translation":"美国的政策加剧了日本的不安全感，有可能导致美国旨在防止的结果 — — 军国主义。","targetForm":"return","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Thus, under almost any scenario, Thaksin’s return could well mark a return to those fraught days of 2006 just before the last coup.","translation":"这样，他信回国几乎肯定会标志着泰国回到2006年上一次政变前苦难重重的日子。","targetForm":"return","senseId":"source-n-1","sourceSenseId":"n-1"}]},"refusal":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"拒绝"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"谢绝","contextReviewed":true},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"[法] 拒绝","contextReviewed":true},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"优先决定权"}],"examples":[{"sentence":"Her refusal to compromise on ethical standards earned her widespread respect among colleagues.","translation":"她拒绝在道德标准上妥协，这为她赢得了同事们的广泛尊重。","targetForm":"refusal","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The company's refusal to negotiate led to a prolonged strike that affected thousands of workers.","translation":"公司拒绝谈判导致了长时间的罢工，影响了数千名工人。","targetForm":"refusal","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Despite the lucrative offer, his polite refusal reflected his commitment to public service.","translation":"尽管报酬丰厚，他礼貌的谢绝反映了他对公共服务的承诺。","targetForm":"refusal","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"The court upheld the defendant's refusal to testify, citing the right against self-incrimination.","translation":"法院支持被告拒绝作证，援引了反对自证其罪的权利。","targetForm":"refusal","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The contract granted the investor a refusal on any future sale of the property, ensuring control.","translation":"合同授予投资者对该财产未来任何出售的优先决定权，从而确保了控制权。","targetForm":"refusal","senseId":"source-n-3","sourceSenseId":"n-3"}]},"resent":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"愤恨"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"憎恶"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"怨恨"}],"examples":[{"sentence":"Employees may resent constant monitoring when it suggests that professional judgement is not trusted.","translation":"当持续监控暗示专业判断不被信任时，员工可能会因此愤恨。","targetForm":"resent","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although residents resented the higher tax, many accepted it once they saw the improvements to local transport.","translation":"尽管居民憎恶更高的税收，看到当地交通改善后，许多人还是接受了。","targetForm":"resented","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"She did not resent her colleague's promotion; instead, she asked what skills would strengthen her own application.","translation":"她并未怨恨同事获得晋升，反而询问哪些技能能增强自己的申请。","targetForm":"resent","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Communities often resent outside decisions that appear well intentioned but ignore local knowledge and priorities.","translation":"社区常会怨恨那些看似善意却忽视当地知识和优先事项的外部决定。","targetForm":"resent","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The researcher resented being judged by publication numbers alone, because careful work sometimes requires years of quiet effort.","translation":"这位研究人员厌恶只按论文数量被评判，因为严谨工作有时需要多年默默投入。","targetForm":"resented","senseId":"source-v-2","sourceSenseId":"v-2"}]},"reference":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"参考"}],"examples":[{"sentence":"When using this information, I will follow any conditions you specify, whether that's anonymity or giving detailed reference.","translation":"在使用这份问卷的信息时，我会遵照您提出的条件，不留您的姓名或者关于您的任何详细信息。","targetForm":"reference","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Tom wanted to check the applicant's character reference before extending an offer.","translation":"汤姆想在发出录取通知前先确认申请人的品行证明。","targetForm":"reference","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The source made reference to Kate and the Queen being seen chatting and smiling together last March.","translation":"知情者提到去年三月有人看到女王和凯萨琳笑着聊天。","targetForm":"reference","senseId":"source-n-1","sourceSenseId":"n-1"}]},"remainder":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"剩余物"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"其他人"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"残余"}],"examples":[{"sentence":"After allocating funds for essential infrastructure, the remainder of the budget was directed toward educational programs that benefit underprivileged communities.","translation":"在为必要的基础设施分配资金后，预算的剩余部分被用于惠及贫困社区的教育项目。","targetForm":"remainder","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"While some team members focused on the theoretical framework, the remainder conducted fieldwork to collect empirical evidence for the study.","translation":"一些团队成员专注于理论框架，而其余成员则进行实地调查，为研究收集实证证据。","targetForm":"remainder","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because the first batch of samples was contaminated, the remainder had to be stored under stricter conditions to ensure the experiment's validity.","translation":"由于第一批样本受到污染，剩余样本必须在更严格的条件下储存，以确保实验的有效性。","targetForm":"remainder","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The company decided to sell the remainder of its inventory at a discount, which not only reduced storage costs but also attracted new customers.","translation":"公司决定打折出售剩余库存，这不仅降低了仓储成本，还吸引了新客户。","targetForm":"remainder","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The researcher spent the morning analyzing the initial data set and devoted the remainder of the day to verifying the results through independent tests.","translation":"研究人员上午分析了初始数据集，并将当天剩余的时间用于通过独立测试验证结果。","targetForm":"remainder","senseId":"source-n-3","sourceSenseId":"n-3"}]},"retire":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"退休"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"退役"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"撤退"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"退去"}],"examples":[{"sentence":"Although she could retire next year, she intends to complete the mentoring programme first.","translation":"尽管她明年就可以退休，她仍打算先完成导师计划。","targetForm":"retire","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The athlete retired from competition when repeated injuries made training difficult to sustain.","translation":"当反复受伤使训练难以持续时，这名运动员从比赛中退役了。","targetForm":"retired","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Because several experienced staff will retire soon, the museum has begun training new conservators.","translation":"由于几名经验丰富的员工即将退休，博物馆已开始培训新的修复师。","targetForm":"retire","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"When the water rose unexpectedly, rescue teams retired from the riverside until conditions became safer.","translation":"水位意外上涨时，救援队从河边撤退，直到条件变得更安全。","targetForm":"retired","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"The company retired the outdated system after a secure replacement had been tested successfully.","translation":"安全替代系统测试成功后，公司淘汰了过时的系统。","targetForm":"retired","senseId":"source-v-4","sourceSenseId":"v-4"}]},"regardless":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adv.","sourceSenseIds":["adj-1"],"sense":"不管"}],"examples":[{"sentence":"Their loss is Myanmar/Burma’s – and South Asia’s – gain, regardless of what Thein or his democratically chosen successors choose to call their country.","translation":"而中国人的损失就是缅甸及南亚的所得，无论登盛或在其之后民主选举出来的后继者选择如何称呼自己的国家。","targetForm":"regardless","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Regardless how many times I try to solve this nasty problem, I always end up failing.","translation":"对于这个棘手的问题，无论我尝试多少次，结果都会以失败告终。","targetForm":"regardless","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"reduce":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"减少"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"降低"}],"examples":[{"sentence":"The unsolved problem is how to reduce those factors pushing people out of their own countries.","translation":"悬而未决的问题是如何遏制推动人们离开祖国的因素。","targetForm":"reduce","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"This puts a new debate center stage: how to reconcile increased action to reduce greenhouse gas emissions with strong economic growth.","translation":"这把一个新争论带到了舞台中央：如何协调越来越多的行动以降低伴随强劲经济增长出现的温室气体排放。","targetForm":"reduce","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"In a developed-country setting, the reality is that going entirely vegetarian for the rest of your life means reducing your emissions by about 2%.","translation":"在发达国家条件下，现实是余生完全吃素可以让你的排放减少大约2 % 。","targetForm":"reducing","senseId":"source-v-1","sourceSenseId":"v-1"}]},"reputation":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"声望"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"名誉"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"名声"}],"examples":[{"sentence":"The university's reputation for academic excellence attracts scholars from every corner of the globe.","translation":"这所大学因其卓越的学术声誉吸引了来自世界各地的学者。","targetForm":"reputation","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"A single scandal can irreparably damage a politician's reputation, which took decades to build.","translation":"一桩丑闻就能无可挽回地损害政治家花了几十年建立起来的声誉。","targetForm":"reputation","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The company's reputation for ethical practices has become its most valuable intangible asset.","translation":"该公司在道德实践方面的声誉已成为其最宝贵的无形资产。","targetForm":"reputation","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In the close-knit community, a person's reputation often precedes any formal introduction.","translation":"在这个关系紧密的社区里，一个人的名声往往先于任何正式介绍。","targetForm":"reputation","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The historian argued that the king's reputation as a tyrant was largely based on biased chronicles.","translation":"历史学家认为，这位国王作为暴君的名声很大程度上是基于有偏见的编年史。","targetForm":"reputation","senseId":"source-n-2","sourceSenseId":"n-2"}]},"responsible":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"有责任的"}],"examples":[{"sentence":"Yes, global warming is happening, and mankind is partly responsible, but these statements are – however eloquent – seriously wrong or misleading.","translation":"是的，全球变暖正在发生，而人类是要承担部分责任，但上述的声明-不管再怎么雄辩-也存在着严重的错误或误导性。","targetForm":"responsible","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"reflection":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"映像"}],"examples":[{"sentence":"Because the lake was perfectly calm, the reflection of the mountains appeared as a flawless mirror image.","translation":"因为湖面异常平静，群山的倒影呈现出完美的镜像。","targetForm":"reflection","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The polished surface provided a clear reflection, which allowed the technician to inspect the underside of the device.","translation":"抛光表面提供了清晰的映像，使技术人员能够检查设备的底部。","targetForm":"reflection","senseId":"source-n-3","sourceSenseId":"n-3"}]},"reconcile":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"使和谐"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"使一致"},{"id":"source-v-6","partOfSpeech":"v.","sourceSenseIds":["v-6"],"sense":"[经] 对帐","contextReviewed":true},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使和解"}],"examples":[{"sentence":"This puts a new debate center stage: how to reconcile increased action to reduce greenhouse gas emissions with strong economic growth.","translation":"这把一个新争论带到了舞台中央：如何协调越来越多的行动以降低伴随强劲经济增长出现的温室气体排放。","targetForm":"reconcile","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Although the two departments had conflicting priorities, the manager helped them reconcile their goals through a series of collaborative workshops.","translation":"尽管两个部门的优先事项存在冲突，但经理通过一系列协作研讨会帮助他们协调了目标。","targetForm":"reconcile","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Because the financial records did not match, the accountant had to reconcile the bank statements with the company's internal accounts.","translation":"由于财务记录不符，会计师不得不将银行对账单与公司内部账目进行核对。","targetForm":"reconcile","senseId":"source-v-6","sourceSenseId":"v-6"},{"sentence":"If communities fail to reconcile historical grievances, long-term peace remains elusive despite superficial agreements.","translation":"如果社区未能化解历史积怨，那么即使有表面协议，长期和平仍遥不可及。","targetForm":"reconcile","senseId":"source-v-1","sourceSenseId":"v-1"}]},"repeat":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"反复"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"重复"}],"examples":[{"sentence":"When a repeat of the error occurred in the manufacturing process, the quality control team implemented stricter inspection protocols.","translation":"当制造过程中再次出现错误时，质量控制团队实施了更严格的检查规程。","targetForm":"repeat","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the television series was popular, the network decided against a repeat of the show due to high production costs.","translation":"尽管这部电视剧很受欢迎，但由于制作成本高昂，电视台决定不重播该剧。","targetForm":"repeat","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the initial survey produced ambiguous results, a repeat of the study with a larger sample size was deemed necessary.","translation":"由于初步调查结果模糊不清，因此认为有必要用更大的样本量重复这项研究。","targetForm":"repeat","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"If a repeat of the security breach happens, the company will face severe penalties under the new data protection regulations.","translation":"如果再次发生安全漏洞，该公司将根据新的数据保护法规面临严厉处罚。","targetForm":"repeat","senseId":"source-n-2","sourceSenseId":"n-2"}]},"refund":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"偿还"}],"examples":[{"sentence":"Customers who are dissatisfied with the product can request a full refund within 30 days, which ensures consumer protection.","translation":"对产品不满意的顾客可以在30天内要求全额退款，这确保了消费者保护。","targetForm":"refund","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The university issued a partial refund to students because campus facilities were closed due to unexpected maintenance work.","translation":"大学向学生发放了部分退款，因为校园设施因意外维修工作而关闭。","targetForm":"refund","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The tax refund system is designed to reimburse individuals who have overpaid their income taxes, thereby correcting fiscal imbalances.","translation":"退税制度旨在偿还那些多缴个人所得税的个人，从而纠正财政失衡。","targetForm":"refund","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"To maintain consumer trust, the company promised a prompt refund for any defective items, provided that they are returned with a receipt.","translation":"为了维护消费者信任，该公司承诺对任何有缺陷的商品迅速退款，前提是凭收据退回。","targetForm":"refund","senseId":"source-n-1","sourceSenseId":"n-1"}]},"recollect":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"回想"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"回忆"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"忆起"}],"examples":[{"sentence":"When I recollect my first semester, I remember how useful regular feedback became.","translation":"当我回想起第一个学期时，我记得定期反馈变得多么有用。","targetForm":"recollect","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Although she could recollect the conversation, she could not remember the exact date of the meeting.","translation":"尽管她能回忆起那次谈话，她却记不起会议的确切日期。","targetForm":"recollect","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The witness recollected seeing a blue bag near the entrance before the event began.","translation":"证人回忆起活动开始前曾在入口附近看到一个蓝色包。","targetForm":"recollected","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Because students recollect information more easily with examples, the teacher added short case studies.","translation":"由于学生通过例子更容易回忆信息，老师加入了简短案例。","targetForm":"recollect","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The exhibition encouraged visitors to recollect family stories while looking at photographs from earlier decades.","translation":"展览鼓励访客在观看早年照片时回想家族故事。","targetForm":"recollect","senseId":"source-v-2","sourceSenseId":"v-2"}]},"revolutionary":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"革命者"}],"examples":[{"sentence":"The statue of the Minute Man commemorates the valiant soldiers who fought in the Revolutionary War.","translation":"民兵雕像是为了纪念独立战争中英勇作战的士兵。","targetForm":"revolutionary","senseId":"source-n-1","sourceSenseId":"n-1"}]},"rely":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"依赖"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"信赖"}],"examples":[{"sentence":"Although modern societies rely heavily on digital infrastructure, this dependence can increase vulnerability during system failures.","translation":"尽管现代社会严重依赖数字基础设施，这种依赖会在系统故障时增加脆弱性。","targetForm":"rely","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Students who rely only on memorisation often struggle to apply knowledge in unfamiliar situations.","translation":"只依赖记忆的学生往往难以在陌生情境中应用知识。","targetForm":"rely","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Because renewable sources are intermittent, many electricity systems still rely on backup generation for stability.","translation":"由于可再生能源具有间歇性，许多电力系统仍依赖备用发电来保持稳定。","targetForm":"rely","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Effective leaders rely on both expertise and emotional intelligence when making difficult decisions.","translation":"高效领导者在作出困难决定时既依靠专业知识，也依靠情商。","targetForm":"rely","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The community can rely on the local library to provide trusted information when rumours spread online.","translation":"当网络谣言传播时，社区可以信赖当地图书馆提供可靠信息。","targetForm":"rely","senseId":"source-v-1","sourceSenseId":"v-1"}]},"react":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"应答","contextReviewed":true},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"起反应"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"反攻"}],"examples":[{"sentence":"Although the feedback was unexpected, she chose to react calmly and ask for a clearer example.","translation":"尽管反馈出乎意料，她仍选择冷静回应并要求更清楚的例子。","targetForm":"react","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"When the market reacts to new information, short-term changes do not always predict long-term outcomes.","translation":"当市场对新信息作出反应时，短期变化并不总能预测长期结果。","targetForm":"reacts","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Because the materials may react differently in heat, the engineers tested them under controlled conditions.","translation":"由于材料在高温下可能反应不同，工程师在受控条件下测试了它们。","targetForm":"react","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The community did not react with anger but organised a meeting to discuss the proposal.","translation":"社区没有愤怒反击，而是组织会议讨论该提案。","targetForm":"react","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"When the patient did not react to the initial treatment, the clinical team reviewed the case carefully.","translation":"当病人对初步治疗没有反应时，临床团队仔细审查了病例。","targetForm":"react","senseId":"source-v-4","sourceSenseId":"v-4"}]},"revise":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"修正"}],"examples":[{"sentence":"In the light of what you told us, I think we should revise our plan.","translation":"根据你所说的话，我认为我们应该重新审视我们的计划。","targetForm":"revise","senseId":"source-n-2","sourceSenseId":"n-2"}]},"relax":{"senseGroups":[{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"休息"},{"id":"source-v-8","partOfSpeech":"v.","sourceSenseIds":["v-8"],"sense":"缓和"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"放松"}],"examples":[{"sentence":"Thus, most of the extra money was spent on staying healthy, having a nice home, traveling and relaxing, and doing a little business.","translation":"归根结底，绝大部分的额外收入被用于医疗保健、购买和装饰家居、旅游、休闲，和做点小生意。","targetForm":"relaxing","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"Although the government decided to relax import restrictions, domestic industries feared a surge in foreign competition.","translation":"尽管政府决定放宽进口限制，但国内产业担心外国竞争激增。","targetForm":"relax","senseId":"source-v-8","sourceSenseId":"v-8"},{"sentence":"Because the strict regulations were hindering innovation, the agency chose to relax certain rules for startups.","translation":"由于严格的法规阻碍了创新，该机构选择为初创企业放宽某些规定。","targetForm":"relax","senseId":"source-v-8","sourceSenseId":"v-8"},{"sentence":"To ensure long-term productivity, companies should encourage employees to relax during breaks rather than work continuously.","translation":"为了确保长期生产力，公司应鼓励员工在休息时放松，而不是持续工作。","targetForm":"relax","senseId":"source-v-1","sourceSenseId":"v-1"}]},"rebellion":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"叛乱"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"反抗"}],"examples":[{"sentence":"Although the rebellion failed to overthrow the regime, it exposed the deep-seated discontent among the rural population.","translation":"尽管叛乱未能推翻政权，但它暴露了农村人口中根深蒂固的不满。","targetForm":"rebellion","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The rebellion, which was fueled by widespread corruption, ultimately led to the establishment of a more transparent government.","translation":"这场由普遍腐败引发的叛乱，最终导致了一个更透明的政府的建立。","targetForm":"rebellion","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The student rebellion of 1968, which challenged authoritarian educational policies, remains a pivotal moment in academic history.","translation":"1968年的学生反抗挑战了威权教育政策，至今仍是学术史上的关键时刻。","targetForm":"rebellion","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"When the rebellion was finally quelled, the government implemented reforms to address the underlying social inequalities.","translation":"当叛乱最终被平息时，政府实施了改革以解决潜在的社会不平等。","targetForm":"rebellion","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because the rebellion disrupted trade routes, neighboring countries experienced severe economic repercussions.","translation":"因为叛乱中断了贸易路线，邻国遭受了严重的经济影响。","targetForm":"rebellion","senseId":"source-n-2","sourceSenseId":"n-2"}]},"reporter":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"记者"}],"examples":[{"sentence":"A responsible reporter must verify facts from multiple sources before publishing a story that could influence public opinion.","translation":"一位负责任的记者在发表可能影响公众舆论的报道之前，必须从多个来源核实事实。","targetForm":"reporter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the reporter faced considerable pressure from authorities, she refused to reveal the identity of her confidential source.","translation":"尽管这位记者面临来自当局的巨大压力，但她拒绝透露机密消息来源的身份。","targetForm":"reporter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The investigative reporter uncovered a series of financial irregularities that had been concealed by the company for years.","translation":"这位调查记者揭露了公司多年来一直隐瞒的一系列财务违规行为。","targetForm":"reporter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The science reporter explained the complex research findings in a way that was accessible to a general audience.","translation":"这位科学记者以一种普通观众都能理解的方式解释了复杂的研究发现。","targetForm":"reporter","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Because the reporter had built a strong network of local contacts, she was able to report on the conflict with remarkable depth.","translation":"由于这位记者建立了强大的当地关系网，她能够以非凡的深度报道这场冲突。","targetForm":"reporter","senseId":"source-n-1","sourceSenseId":"n-1"}]},"realistic":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"现实的"}],"examples":[{"sentence":"This is the only realistic way to help those – probably a majority – who want genuine democracy, not an election used as a route to domination.","translation":"这是唯一现实的方法能够帮助多数真正渴望民主的群体，而不是利用选举走上独裁之路。","targetForm":"realistic","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"religious":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"宗教性的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"宗教上的"},{"id":"source-adj-4","partOfSpeech":"adj.","sourceSenseIds":["adj-4"],"sense":"严谨的"}],"examples":[{"sentence":"The museum presented religious manuscripts alongside the tools used to preserve them for future study.","translation":"博物馆展出了宗教手稿，并介绍了用于保存这些手稿以供后人研究的工具。","targetForm":"religious","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the village was small, its religious festival brought together families from the surrounding valleys.","translation":"尽管村庄不大，它的宗教节庆仍把周边山谷的家庭聚集在一起。","targetForm":"religious","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The university protects religious expression while requiring every student to respect the rights of others.","translation":"这所大学保障宗教表达，同时要求每位学生尊重他人的权利。","targetForm":"religious","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"She kept a religious record of each experiment, which allowed the team to identify a minor error months later.","translation":"她一丝不苟地记录每一次实验，因此团队几个月后仍能找出一个小错误。","targetForm":"religious","senseId":"source-adj-4","sourceSenseId":"adj-4"},{"sentence":"With religious attention to detail, the conservator documented every repair before touching the fragile map.","translation":"修复师以极其严谨的态度，在处理这幅脆弱地图前记录了每一处修补情况。","targetForm":"religious","senseId":"source-adj-4","sourceSenseId":"adj-4"}]},"remark":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"评论"}],"examples":[{"sentence":"Dear Africa: We apologize for Trump’s obscene remarks insulting your countries in January.","translation":"亲爱的非洲：我们为特朗普1月份冒犯你们的国家的猥琐言论致歉。","targetForm":"remarks","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The remark you made at the party about Lisa's weight was totally uncalled for.","translation":"你在聚会中针对Lisa体重作出的评论是完全不适当的。","targetForm":"remark","senseId":"source-n-1","sourceSenseId":"n-1"}]},"reflect":{"senseGroups":[{"id":"source-v-7","partOfSpeech":"v.","sourceSenseIds":["v-7"],"sense":"考虑"}],"examples":[{"sentence":"Any religious minority in quest of a place in the European project would do well to reflect on that theological shift.","translation":"任何宗教少数派在欧洲计划中探寻一席之地时，都会仔细考虑其在神学上的转变。","targetForm":"reflect","senseId":"source-v-7","sourceSenseId":"v-7"}]},"resign":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"辞职"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"放弃"},{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"屈从"}],"examples":[{"sentence":"The director resigned after the inquiry found that warnings from staff had not been passed to the board.","translation":"调查发现员工的警告未被传达给董事会后，主任辞职了。","targetForm":"resigned","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Although she resigned from the committee, she remained willing to advise the group on the technical details.","translation":"尽管她辞去了委员会职务，仍愿意就技术细节向团队提供建议。","targetForm":"resigned","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The company resigned its exclusive claim to the name once historical records showed that another group had used it first.","translation":"历史记录表明另一团体更早使用该名称后，公司放弃了对该名称的独占主张。","targetForm":"resigned","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"After weeks of delay, residents resigned themselves to a longer journey while the damaged bridge was rebuilt.","translation":"延误数周后，居民无奈接受在受损桥梁重建期间要走更长路程。","targetForm":"resigned","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Rather than resigning herself to an unclear decision, she requested the documents on which the conclusion had been based.","translation":"她没有无奈接受含糊的决定，而是要求查看作出结论所依据的文件。","targetForm":"resigning","senseId":"source-v-4","sourceSenseId":"v-4"}]},"replace":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"替换"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"代替"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"放回"},{"id":"source-other-1","partOfSpeech":"计算机","sourceSenseIds":["other-1"],"sense":"计算机中替换或更新文件","contextReviewed":true}],"examples":[{"sentence":"The council replaced the damaged pipes before winter, when frozen ground would have made repairs far more difficult.","translation":"委员会在冬季前更换了损坏管道，因为地面冻结后维修会困难得多。","targetForm":"replaced","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Digital tools can support teachers, but they cannot replace the careful judgement needed to respond to each learner.","translation":"数字工具可以支持教师，但无法取代回应每位学习者所需的审慎判断。","targetForm":"replace","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"After consulting the map, she replaced it in the drawer so that the next visitor could find it easily.","translation":"查阅地图后，她把它放回抽屉，以便下一位访客容易找到。","targetForm":"replaced","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The technician replaced the missing file with a verified copy, which restored the report without altering its original data.","translation":"技术员用经核实的副本替换缺失文件，在不改动原始数据的情况下恢复了报告。","targetForm":"replaced","senseId":"source-other-1","sourceSenseId":"other-1"},{"sentence":"Although the new editor replaced several paragraphs, she preserved the evidence that supported the central conclusion.","translation":"尽管新编辑替换了几个段落，她仍保留了支持核心结论的证据。","targetForm":"replaced","senseId":"source-v-2","sourceSenseId":"v-2"}]},"rebel":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"反叛者"}],"examples":[{"sentence":"Rebels stomped on the enemy’s flags as a sign of defiance.","translation":"反叛者践踏敌人的旗帜，以示挑衅。","targetForm":"rebels","senseId":"source-n-2","sourceSenseId":"n-2"}]},"revive":{"senseGroups":[{"id":"source-v-9","partOfSpeech":"v.","sourceSenseIds":["v-9"],"sense":"恢复精神"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"使复兴"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"使振奋"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"重播"}],"examples":[{"sentence":"Fresh air and a short break revived the audience after the technical session had run longer than planned.","translation":"技术环节比计划更长后，新鲜空气和短暂休息让听众重新恢复精神。","targetForm":"revived","senseId":"source-v-9","sourceSenseId":"v-9"},{"sentence":"Although the market had declined, the council hopes to revive it through independent shops and evening events.","translation":"尽管市场已经衰落，市政部门希望通过独立商店和夜间活动使它重新兴旺。","targetForm":"revive","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Because neighbours lacked a meeting place, a public garden could revive the neglected street as a shared space.","translation":"由于邻居缺少聚会场所，一座公共花园能把被忽视的街道重新变为共享空间。","targetForm":"revive","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The unexpectedly kind message revived her confidence just before she presented the proposal to the board.","translation":"这条出乎意料的善意信息在她向董事会展示提案前重新振奋了她的信心。","targetForm":"revived","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The theatre revived a rarely performed comedy, allowing modern audiences to hear its sharp social observations.","translation":"剧院重新上演了一部很少演出的喜剧，让当代观众听到其中尖锐的社会观察。","targetForm":"revived","senseId":"source-v-5","sourceSenseId":"v-5"}]},"recite":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"背诵"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"朗读"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"叙述"}],"examples":[{"sentence":"The student could recite the opening lines accurately, yet still needed to explain the poem's central image.","translation":"这名学生能准确背诵开头几行，却仍需要解释诗歌的核心意象。","targetForm":"recite","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"Rather than reciting a long list of dates, the guide used a timeline to make the sequence easier to remember.","translation":"向导没有背诵一长串日期，而是使用时间线让顺序更易记住。","targetForm":"reciting","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"During the ceremony, the actor recited a short passage with clear pacing and careful emphasis.","translation":"仪式期间，演员以清晰节奏和恰当重音朗读了一段短文。","targetForm":"recited","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"The interpreter asked the speaker to pause so that she could recite the instructions accurately in the second language.","translation":"口译员请讲话者停顿一下，以便她能用第二种语言准确复述指示。","targetForm":"recite","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Before approving the request, the clerk recited the key details to ensure that neither date had been copied incorrectly.","translation":"批准请求前，办事员复述了关键细节，以确保两个日期都没有抄错。","targetForm":"recited","senseId":"source-v-3","sourceSenseId":"v-3"}]},"reality":{"senseGroups":[{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"现实","contextReviewed":true},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"逼真"}],"examples":[{"sentence":"In reality, a timetable that looks efficient on paper may fail if it leaves no room for unexpected delays.","translation":"实际上，一份纸面上看似高效的时间表，如果没有为意外延误留出余地，可能无法实行。","targetForm":"reality","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"The financial reality forced the organisers to reduce the scale of the festival while protecting its educational programme.","translation":"财务现实迫使组织者缩小节庆规模，同时保留其教育项目。","targetForm":"reality","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"Although the model is elegant, reality is often more complex than the assumptions used to build it.","translation":"尽管模型很精巧，现实往往比构建它所用的假设更复杂。","targetForm":"reality","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"The exhibition used sound, light, and texture to give visitors a stronger sense of historical reality.","translation":"展览利用声音、光线和质感，让访客获得更强的历史真实感。","targetForm":"reality","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Without direct consultation, the proposed service risks overlooking the daily reality of people who rely on it.","translation":"如果没有直接咨询，拟议服务可能会忽视依赖它的人们的日常现实。","targetForm":"reality","senseId":"source-n-5","sourceSenseId":"n-5"}]},"rectify":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"矫正"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"改正"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"校正"}],"examples":[{"sentence":"To rectify the imbalance in resource allocation, the committee proposed a new policy that prioritizes underserved communities.","translation":"为了纠正资源分配的不平衡，委员会提出了一项优先考虑服务不足社区的新政策。","targetForm":"rectify","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Although the company acknowledged the accounting error, it took immediate steps to rectify the discrepancy before the audit.","translation":"尽管公司承认了会计错误，但它立即采取措施在审计前纠正了差异。","targetForm":"rectify","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Because the experimental data contained anomalies, the researchers had to rectify the calibration of the instruments before proceeding.","translation":"由于实验数据包含异常，研究人员在继续之前必须纠正仪器的校准。","targetForm":"rectify","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"While the software patch was intended to rectify security flaws, it inadvertently introduced new vulnerabilities that required further attention.","translation":"虽然软件补丁旨在修复安全漏洞，但它无意中引入了需要进一步关注的新漏洞。","targetForm":"rectify","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"The government launched a campaign to rectify public misconceptions about vaccination, which had led to a decline in immunization rates.","translation":"政府发起了一场运动来纠正公众对疫苗接种的误解，这些误解导致了免疫接种率的下降。","targetForm":"rectify","senseId":"source-v-2","sourceSenseId":"v-2"}]},"review":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"回顾"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"复习"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"评论"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"复审"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"评论"}],"examples":[{"sentence":"The annual review identified where the programme had met its targets and where further support was needed.","translation":"年度回顾指出了项目在哪些方面达到目标，以及在哪些方面还需要更多支持。","targetForm":"review","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"A short review before sleep can help students connect new vocabulary with words they learned earlier.","translation":"睡前进行简短复习能帮助学生把新词汇与先前学过的词联系起来。","targetForm":"review","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The newspaper review praised the exhibition's careful research while questioning the layout of its final room.","translation":"报纸评论赞扬了展览严谨的研究，同时质疑其最后一个展厅的布局。","targetForm":"review","senseId":"source-n-5","sourceSenseId":"n-5"},{"sentence":"Before approving the plan, the committee will review every cost estimate and the assumptions behind it.","translation":"批准方案前，委员会将审查每一项成本估算及其背后的假设。","targetForm":"review","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"The critic reviewed the novel by comparing its structure with the author's earlier work.","translation":"评论家通过比较这部小说的结构与作者早期作品，对它进行了评论。","targetForm":"reviewed","senseId":"source-v-3","sourceSenseId":"v-3"}]},"resolution":{"senseGroups":[{"id":"source-n-7","partOfSpeech":"n.","sourceSenseIds":["n-7"],"sense":"解答"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"决心"}],"examples":[{"sentence":"And yet, for all the woe, a resolution remains possible; to achieve it, five steps must be taken without delay.","translation":"但尽管局势如此痛苦，仍然保留着和平解决的生机；要想实现这个目标，必须立即实行五步走政策。","targetForm":"resolution","senseId":"source-n-7","sourceSenseId":"n-7"},{"sentence":"My New Year's resolution is to learn how to play the ocarina.","translation":"我新年的愿望是学会吹奥卡利纳埙。","targetForm":"resolution","senseId":"source-n-2","sourceSenseId":"n-2"}]},"recognition":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"识别"},{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"认识"}],"examples":[{"sentence":"Although the algorithm achieved high accuracy, its lack of facial recognition in low-light conditions limited its practical use.","translation":"尽管该算法达到了很高的准确率，但它在低光条件下缺乏面部识别能力，限制了其实际应用。","targetForm":"recognition","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The company's brand recognition grew significantly after it launched a clever marketing campaign that resonated with younger consumers.","translation":"该公司在推出了一项引起年轻消费者共鸣的巧妙营销活动后，品牌认知度显着提升。","targetForm":"recognition","senseId":"source-n-6","sourceSenseId":"n-6"}]},"relay":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"驿马"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"中继"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"接力"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"分程传递"}],"examples":[{"sentence":"In the nineteenth century, a relay of horses carried messages between towns more quickly than a single rider could.","translation":"十九世纪，一组驿马比单个骑手更快地在城镇之间传递消息。","targetForm":"relay","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The engineer replaced the faulty relay so that the alarm could send a signal to the control room.","translation":"工程师更换了故障中继器，以便警报能向控制室发送信号。","targetForm":"relay","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"During the relay, each runner practised the handover carefully because a smooth exchange matters more than raw speed.","translation":"接力赛中，每位跑者仔细练习交接，因为顺畅交棒比单纯速度更重要。","targetForm":"relay","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The coordinator relayed the revised timetable to volunteers before the event, thereby preventing unnecessary confusion.","translation":"协调员在活动前把修订后的时间表转达给志愿者，从而避免不必要的混乱。","targetForm":"relayed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"When the station receives a warning, it relays the information to nearby communities through several channels.","translation":"当车站收到预警时，它会通过多种渠道把信息转发给附近社区。","targetForm":"relays","senseId":"source-v-1","sourceSenseId":"v-1"}]},"reinforce":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"加强"}],"examples":[{"sentence":"France’s seemingly natural propensity to intervene is reinforced in this case by three key factors: Sarkozy, Qaddafi, and the context of a wider Arab revolution.","translation":"此次有三种关键因素巩固了法国似乎与生俱来的干涉倾向： 萨科奇、卡扎菲和阿拉伯革命大环境。","targetForm":"reinforced","senseId":"source-v-1","sourceSenseId":"v-1"}]},"republic":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"共和政体"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"共和国"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"团体"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"界"}],"examples":[{"sentence":"A republic depends on institutions that limit power, while also allowing citizens to replace leaders through lawful procedures.","translation":"共和国依赖限制权力的制度，同时让公民能够通过合法程序更换领导人。","targetForm":"republic","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the republic had written protections for debate, those protections required independent courts to be meaningful in practice.","translation":"尽管该共和国对辩论有书面保障，这些保障仍需要独立法院才能在实践中有意义。","targetForm":"republic","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The essay describes a republic of letters in which scholars exchanged ideas across borders long before modern communication systems.","translation":"文章描述了学术共同体，即学者在现代通信系统出现前便跨越边界交流思想。","targetForm":"republic","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The speakers argued that the republic's constitutional design should be judged by how it protects both majority rule and minority rights.","translation":"演讲者认为，应通过共和国宪制设计如何同时保护多数决与少数权利来评价它。","targetForm":"republic","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"In older writing, republic can refer broadly to a realm of shared concern rather than to a particular nation-state.","translation":"在较早的写作中，republic 可宽泛指涉共同关切的领域，而非特定民族国家。","targetForm":"republic","senseId":"source-n-4","sourceSenseId":"n-4"}]},"relevant":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"有关联的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"适当的"}],"examples":[{"sentence":"The writer selected only evidence relevant to the question, rather than filling the essay with unrelated background.","translation":"作者只选择与问题相关的证据，而没有用无关背景填满文章。","targetForm":"relevant","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the report is old, its discussion of access remains relevant to the current debate about public services.","translation":"尽管报告较旧，它对可及性的讨论仍与当前公共服务争论相关。","targetForm":"relevant","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Before speaking, the witness was asked to distinguish relevant observations from details that could not be checked.","translation":"发言前，证人被要求区分相关观察与无法核实的细节。","targetForm":"relevant","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"A relevant example should clarify the claim by showing how the principle works in a specific setting.","translation":"恰当的例子应通过展示原则如何在特定环境中发挥作用来阐明论点。","targetForm":"relevant","senseId":"source-adj-3","sourceSenseId":"adj-3"},{"sentence":"The committee requested all relevant documents so that its decision could be explained openly afterwards.","translation":"委员会要求提供所有相关文件，以便之后能公开说明决定。","targetForm":"relevant","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"recipient":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"领受的"}],"examples":[{"sentence":"May the recipients of Trump’s sudden solicitude be as wary of this new friend as they are of their enemies.","translation":"特朗普突如其来的关怀对象也许对这位新朋友的担心不下于对他们的敌人。","targetForm":"recipients","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"regular":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"规则的"},{"id":"source-adj-6","partOfSpeech":"adj.","sourceSenseIds":["adj-6"],"sense":"定期的"},{"id":"source-adj-8","partOfSpeech":"adj.","sourceSenseIds":["adj-8"],"sense":"合格的"},{"id":"source-adj-9","partOfSpeech":"adj.","sourceSenseIds":["adj-9"],"sense":"常备军的"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"正式队员"}],"examples":[{"sentence":"The tiles formed a regular pattern, which made it easier for visitors to follow the path through the garden.","translation":"瓷砖组成了规则图案，使访客更容易沿着花园中的小路前行。","targetForm":"regular","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"Although the museum is open daily, regular guided tours take place only on Saturday mornings.","translation":"尽管博物馆每天开放，定期导览只在周六上午举行。","targetForm":"regular","senseId":"source-adj-6","sourceSenseId":"adj-6"},{"sentence":"The firm recruited a regular employee after the temporary role developed into a long-term responsibility.","translation":"临时岗位发展为长期职责后，这家公司招聘了一名正式员工。","targetForm":"regular","senseId":"source-adj-8","sourceSenseId":"adj-8"},{"sentence":"The history lecture distinguished regular forces from volunteers who joined only during a short local campaign.","translation":"历史讲座把常备军与只在短期地方行动中加入的志愿者区分开来。","targetForm":"regular","senseId":"source-adj-9","sourceSenseId":"adj-9"},{"sentence":"As a regular at the reading group, she often helped newcomers find the text before discussion began.","translation":"作为读书会的常客，她常在讨论开始前帮助新人找到文本。","targetForm":"regular","senseId":"source-n-2","sourceSenseId":"n-2"}]},"relative":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"亲戚"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"关系词"},{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"有关系的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"相对的"},{"id":"source-adj-3","partOfSpeech":"adj.","sourceSenseIds":["adj-3"],"sense":"比较的"}],"examples":[{"sentence":"Although the village was far away, a relative travelled there every summer to visit their grandmother.","translation":"尽管村子很远，一位亲戚每年夏天都会去看望他们的祖母。","targetForm":"relative","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"In the phrase the book that changed my mind, that functions as a relative word linking the noun to its clause.","translation":"在 the book that changed my mind 这一短语中，that 作关系词，把名词与从句连接起来。","targetForm":"relative","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Please attach every relative document so that the committee can assess the proposal in context.","translation":"请附上所有相关文件，以便委员会结合背景评估该提案。","targetForm":"relative","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The apparent size of the moon is relative to its distance from the observer.","translation":"月亮的视大小与它到观察者的距离有关，是相对的。","targetForm":"relative","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"In relative terms, the library's budget rose sharply, although the actual increase was modest.","translation":"按相对标准来看，图书馆预算大幅上升，尽管实际增加的金额不多。","targetForm":"relative","senseId":"source-adj-3","sourceSenseId":"adj-3"}]},"revenge":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"复仇"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"报复"}],"examples":[{"sentence":"If societies prioritize revenge over rehabilitation, they risk entrenching a culture of violence that undermines social cohesion.","translation":"如果社会将复仇置于改造之上，就有可能巩固一种破坏社会凝聚力的暴力文化。","targetForm":"revenge","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because revenge is driven by anger rather than reason, decisions made in its pursuit frequently lead to unintended consequences.","translation":"由于复仇是由愤怒而非理性驱动的，在追求复仇时做出的决定常常会导致意想不到的后果。","targetForm":"revenge","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Historical conflicts show that revenge rarely resolves disputes, whereas diplomatic negotiations can achieve lasting peace.","translation":"历史冲突表明，复仇很少能解决争端，而外交谈判则能实现持久的和平。","targetForm":"revenge","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although revenge may offer a fleeting sense of justice, it often perpetuates a cycle of retaliation that harms all involved.","translation":"尽管复仇可能带来短暂的正义感，但它往往会使报复循环持续下去，伤害所有相关的人。","targetForm":"revenge","senseId":"source-n-3","sourceSenseId":"n-3"}]},"restaurant":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"餐馆"}],"examples":[{"sentence":"The restaurant reduced food waste by planning its menu around seasonal ingredients and reliable local suppliers.","translation":"这家餐馆围绕时令食材和可靠本地供应商规划菜单，从而减少食物浪费。","targetForm":"restaurant","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the restaurant was small, its clear reservation system prevented long queues during the busiest hours.","translation":"尽管餐馆很小，清晰的预约系统仍防止了最繁忙时段出现长队。","targetForm":"restaurant","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The restaurant trained new staff to describe dishes clearly for visitors with different dietary preferences.","translation":"餐馆培训新员工，为有不同饮食偏好的访客清楚介绍菜品。","targetForm":"restaurant","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When the restaurant moved online orders to one screen, the kitchen made fewer errors during busy evenings.","translation":"餐馆把线上订单集中到一个屏幕后，厨房在繁忙夜晚出错更少。","targetForm":"restaurant","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Before opening the restaurant, the owners consulted neighbours about noise, deliveries, and accessible entrance routes.","translation":"开设餐馆前，店主就噪音、配送和无障碍入口路线征询了邻居意见。","targetForm":"restaurant","senseId":"source-n-1","sourceSenseId":"n-1"}]},"refugee":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"难民"}],"examples":[{"sentence":"Third, we need to accept the fact that most of the refugees arriving in the EU will not return home.","translation":"第三，我们需要接受一个事实，即大部分到达欧盟的难民不会回去。","targetForm":"refugees","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"We also must expand our capacity to host refugees through resettlement and other legal pathways – such as student, work, and family reunification visas.","translation":"我们还必须扩大我们通过安置及其他合法途径接纳难民的能力 — — 包括发放留学、工作签证和家庭团聚签证。","targetForm":"refugees","senseId":"source-n-1","sourceSenseId":"n-1"}]},"reliable":{"senseGroups":[{"id":"source-adj-1","partOfSpeech":"adj.","sourceSenseIds":["adj-1"],"sense":"可靠的"},{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"可信赖的"}],"examples":[{"sentence":"Although the archive is extensive, only reliable sources should be cited in a formal research paper.","translation":"尽管档案资料很丰富，正式研究论文中仍应只引用可靠来源。","targetForm":"reliable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"A reliable colleague raises concerns early rather than allowing a small error to become a costly problem.","translation":"可靠的同事会及早提出疑虑，而不会让小错误演变成代价高昂的问题。","targetForm":"reliable","senseId":"source-adj-2","sourceSenseId":"adj-2"},{"sentence":"Because the forecast relied on decades of observations, the scientists considered its long-term trend reliable.","translation":"由于预测依据数十年的观测数据，科学家认为其长期趋势是可靠的。","targetForm":"reliable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"When public transport is reliable, commuters are more willing to leave their cars at home.","translation":"公共交通可靠时，通勤者更愿意把汽车留在家中。","targetForm":"reliable","senseId":"source-adj-1","sourceSenseId":"adj-1"},{"sentence":"The conclusion remains reliable only if the same method produces similar results in an independent study.","translation":"只有当同一方法在独立研究中得出相似结果时，这个结论才仍然可信。","targetForm":"reliable","senseId":"source-adj-1","sourceSenseId":"adj-1"}]},"recover":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"恢复"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"重新获得"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"痊愈"}],"examples":[{"sentence":"My strong belief is that if these policies are followed, by the end of 2009, if not sooner, the world economy will start recovering from the crisis.","translation":"我坚信如果实施这些政策，世界经济将最晚在2009年末开始从危机中复苏。","targetForm":"recovering","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Efforts to recover the stolen artifacts have intensified, which demonstrates the government's commitment to cultural preservation.","translation":"追回被盗文物的努力已经加强，这表明政府对文化保护的承诺。","targetForm":"recover","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"The patient was able to recover quickly because she followed the doctor's advice and maintained a positive attitude.","translation":"病人能够迅速康复，因为她遵循了医生的建议并保持积极的态度。","targetForm":"recover","senseId":"source-v-5","sourceSenseId":"v-5"}]},"rehearsal":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"预演"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"排演"}],"examples":[{"sentence":"A thorough rehearsal of the evacuation plan ensured that all employees knew exactly where to go during the drill.","translation":"对疏散计划的彻底演练确保了所有员工在演习期间确切知道该去哪里。","targetForm":"rehearsal","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the rehearsal went smoothly, the lead actor still felt nervous about the upcoming premiere.","translation":"尽管排练进行得很顺利，但主演对即将到来的首映仍感到紧张。","targetForm":"rehearsal","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The director used the final rehearsal to fine-tune the lighting cues, which were crucial for creating the desired atmosphere.","translation":"导演利用最后一次排练来微调灯光提示，这对于营造所需氛围至关重要。","targetForm":"rehearsal","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Because the rehearsal was scheduled for early morning, the cast members had to arrive at the theater by six o'clock.","translation":"由于排练安排在清晨，演员们必须在六点前到达剧院。","targetForm":"rehearsal","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"The band decided to hold an extra rehearsal to perfect the new song, which they would debut at the festival.","translation":"乐队决定举行一次额外排练来完善新歌，他们将在音乐节上首次演唱这首歌。","targetForm":"rehearsal","senseId":"source-n-2","sourceSenseId":"n-2"}]},"reckon":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"认为"}],"examples":[{"sentence":"Islamic fundamentalists reckon that what the rest of us regard as the liberalizing influence of technological progress and globalization is a brash re-run of Western colonialism.","translation":"以色列原教旨主义者认为我们其他人眼中技术进步和全球化的自由化影响反应出西方殖民主义不可一世的重新抬头。","targetForm":"reckon","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Rising inflation is certainly not inevitable, but, in both the US and Europe, it has become a risk to be reckoned with.","translation":"通胀抬头绝不是不可避免的，但是，不管是美国还是欧洲，这都已成为不得不考虑的风险。","targetForm":"reckoned","senseId":"source-v-4","sourceSenseId":"v-4"}]},"reign":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"统治"}],"examples":[{"sentence":"Although the reign of Louis XIV is often associated with the splendor of Versailles, it also left France burdened by massive debt.","translation":"尽管路易十四的统治常与凡尔赛宫的辉煌联系在一起，但它也使法国背负了巨额债务。","targetForm":"reign","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"During the reign of Emperor Wu of Han, the Silk Road was established, which facilitated trade and cultural exchange between East and West.","translation":"在汉武帝统治期间，丝绸之路得以建立，促进了东西方之间的贸易和文化交流。","targetForm":"reign","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"The emperor's reign came to an end when a military coup forced him to flee the capital, thereby plunging the nation into chaos.","translation":"当一场军事政变迫使他逃离首都时，这位皇帝的统治结束了，从而使国家陷入混乱。","targetForm":"reign","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"Historians note that the reign of Elizabeth I was marked by a flourishing of English drama, with playwrights such as Shakespeare producing their greatest works.","translation":"历史学家指出，伊丽莎白一世的统治以英国戏剧的繁荣为标志，莎士比亚等剧作家创作了他们最伟大的作品。","targetForm":"reign","senseId":"source-v-4","sourceSenseId":"v-4"}]},"research":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"研究"}],"examples":[{"sentence":"However, such incentives do not address the problem of low-quality education, and research shows that the benefits do not always outweigh the costs.","translation":"然而，这种激励措施并没有解决教育质量低的问题，并且研究表明其利益并不总是超出成本。","targetForm":"research","senseId":"source-n-1","sourceSenseId":"n-1"}]},"refuge":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"避难所"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"避难"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"庇护"}],"examples":[{"sentence":"The restored wetland provides refuge for birds that need quiet nesting areas during the busiest tourist months.","translation":"修复后的湿地为鸟类提供栖息避难之处，它们在旅游最繁忙的月份需要安静的筑巢区域。","targetForm":"refuge","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Although the city centre was crowded, the small reading room offered refuge from the noise and constant movement.","translation":"尽管市中心拥挤，这间小阅览室仍提供了躲避噪音和持续人流的安静之所。","targetForm":"refuge","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"During the storm, residents took refuge in the community hall until the damaged power lines had been inspected.","translation":"暴风雨期间，居民在社区礼堂避难，直到受损电线被检查完毕。","targetForm":"refuge","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The agreement offered legal refuge to families whose homes had become unsafe after the earthquake.","translation":"该协议向地震后家园变得不安全的家庭提供了法律庇护。","targetForm":"refuge","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"The old theatre became a refuge for local artists, who used the unused rooms to rehearse and share ideas.","translation":"这座老剧院成了当地艺术家的栖身之处，他们用闲置房间排练并交流想法。","targetForm":"refuge","senseId":"source-n-1","sourceSenseId":"n-1"}]},"regret":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"抱歉"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"遗憾"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"后悔"}],"examples":[{"sentence":"I regret that I will be unable to meet you on February 27 owing to an unexpected matter.","translation":"因为临时有事，我很抱歉在2月27日那天不能跟您碰面了。","targetForm":"regret","senseId":"source-n-4","sourceSenseId":"n-4"},{"sentence":"Every time I leave, I'm of full the regret that I haven't fully said goodbye.","translation":"我很遗憾每次离开的时候，都没有好好地道别。","targetForm":"regret","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When I ask people what they regret most about high school, they nearly all say the same thing: that they wasted so much time.","translation":"当我问人家高中时代他们最后悔的是什么时，他们几乎所有人都回答一致：他们浪费了那么多时间。","targetForm":"regret","senseId":"source-n-2","sourceSenseId":"n-2"}]},"repression":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"压抑"}],"examples":[{"sentence":"The repression of free speech, unless challenged by civil society, can become deeply entrenched in a nation's laws.","translation":"对言论自由的压制，除非受到公民社会的挑战，否则可能在一个国家的法律中根深蒂固。","targetForm":"repression","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Historians note that cultural repression during that period stifled artistic expression, thereby delaying social progress.","translation":"历史学家指出，那个时期的文化压制扼杀了艺术表达，从而延缓了社会进步。","targetForm":"repression","senseId":"source-n-2","sourceSenseId":"n-2"}]},"reason":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"理由"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"原因"}],"examples":[{"sentence":"Despite all of this, there were compelling reasons to believe that Modi’s government would keep Rajan on board.","translation":"尽管如此，人们仍有充分的理由相信莫迪政府会让拉詹留任。","targetForm":"reasons","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"That is one reason why populism is so dangerous – and why even places as idyllic as Lake Wobegon are not immune to it.","translation":"这解释了民粹主义为什么如此危险 — — 以及为什么就连沃比冈湖这样的诗画田园之地都不能免俗。","targetForm":"reason","senseId":"source-n-2","sourceSenseId":"n-2"}]},"requirement":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"需求"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"必要条件"},{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"要求"},{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"合同要求","contextReviewed":true}],"examples":[{"sentence":"The housing survey measured the requirement for smaller homes, because many older residents wanted to remain in the area.","translation":"住房调查衡量了小型住宅的需求，因为许多老年居民希望留在本地区。","targetForm":"requirement","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"A basic requirement for the course is the ability to read academic articles and discuss them critically.","translation":"这门课程的一项基本要求是能够阅读学术文章并批判性讨论它们。","targetForm":"requirement","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Although the design was attractive, it failed one safety requirement and had to be revised before production.","translation":"尽管设计很吸引人，它仍未达到一项安全要求，必须在生产前修改。","targetForm":"requirement","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Before submitting the proposal, the team checked every requirement in the funding guidance against its final draft.","translation":"提交提案前，团队把资助指南中的每项要求与最终草稿逐一核对。","targetForm":"requirement","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The supplier met the contract requirement to report delays promptly, which allowed the client to adjust the timetable.","translation":"供应商满足了合同中及时报告延误的要求，使客户能够调整时间表。","targetForm":"requirement","senseId":"source-n-5","sourceSenseId":"n-5"}]},"respective":{"senseGroups":[{"id":"source-adj-2","partOfSpeech":"adj.","sourceSenseIds":["adj-2"],"sense":"各自的"}],"examples":[{"sentence":"The two men held very different views about how best to guarantee Israel’s security, and it is worth recapitulating their respective arguments.","translation":"两人对如何更好地保证以色列的安全的问题意见强烈相左，在这里有必要概括一下他们各自的观点。","targetForm":"respective","senseId":"source-adj-2","sourceSenseId":"adj-2"}]},"revolve":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"(使)旋转"}],"examples":[{"sentence":"The word came to be used for all small heavenly bodies revolving about larger ones.","translation":"这个词后来被用来指代围绕大天体的小天体。","targetForm":"revolving","senseId":"source-v-1","sourceSenseId":"v-1"}]},"replacement":{"senseGroups":[{"id":"source-n-5","partOfSpeech":"n.","sourceSenseIds":["n-5"],"sense":"置换","contextReviewed":true}],"examples":[{"sentence":"History develops through the replacement of the old by the new.","translation":"新事物取代旧事物推动历史发展。","targetForm":"replacement","senseId":"source-n-5","sourceSenseId":"n-5"}]},"resemble":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"类似"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"相似"}],"examples":[{"sentence":"He speaks English so fluently that he resembles an American.","translation":"他说英语流利得就好像他是美国人。","targetForm":"resembles","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"All happy families resemble each other, each unhappy family is unhappy in its own way.","translation":"幸福家庭的幸福原因全都大同小异，但悲惨的家庭却往往各自有各自的惨法。","targetForm":"resemble","senseId":"source-v-1","sourceSenseId":"v-1"}]},"remind":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"提醒"}],"examples":[{"sentence":"Sixty years later, the Arab-Israeli conflict reminds us that the Jews’ journey back to history continues.","translation":"六十年之后，阿拉伯—以色列冲突提醒着我们犹太人重返历史的征程仍在继续。","targetForm":"reminds","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"At the same time, complex models can be useful for illustrating special cases and reminding us that the world is a messy place.","translation":"与此同时，复杂模型在说明特殊情况、提醒我们世界是一个混乱场所方面很有用。","targetForm":"reminding","senseId":"source-v-1","sourceSenseId":"v-1"}]},"respond":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"响应"}],"examples":[{"sentence":"Unfortunately, there is little agreement about the nature of those grievances and therefore no consensus on how to respond.","translation":"遗憾的是，对这些不满属于何种性质几乎没有达成一致的意见，因此也就谈不上就如何响应达成共识。","targetForm":"respond","senseId":"source-v-3","sourceSenseId":"v-3"}]},"result":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"结果"}],"examples":[{"sentence":"Another powerful measure would be to protect and restore natural ecosystems, which could result in the storage of 220-330 gigatons of CO2 worldwide .","translation":"另一项强力措施是保护和重建自然生态系统，这样可以储存2,200—3,300亿吨二氧化碳。","targetForm":"result","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Moreover, when economists adjust their message to fit their audience, the result is the opposite of what is intended: they rapidly lose credibility.","translation":"此外，当经济学家根据受众来调整信息时，往往会取得截然相反的效果：他们会以惊人的速度丧失公信力。","targetForm":"result","senseId":"source-n-1","sourceSenseId":"n-1"}]},"responsibility":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"责任"}],"examples":[{"sentence":"The responsibility for stimulating the economy in the next downturn will therefore fall to fiscal policy – changes in taxes and government spending.","translation":"因此，在下一次衰退中，刺激经济的重任降落在财政政策上 — — 即税收和政府支出的变化。","targetForm":"responsibility","senseId":"source-n-1","sourceSenseId":"n-1"}]},"recruit":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"新会员"}],"examples":[{"sentence":"The plan is to recruit 5 Java engineers before the end of next month.","translation":"计划是在下月底之前招聘5名Java工程师。","targetForm":"recruit","senseId":"source-n-3","sourceSenseId":"n-3"}]},"recycle":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"使再循环"}],"examples":[{"sentence":"We must make the utmost effort to reduce the use of plastic packaging, and also to recycle all waste plastic.","translation":"我们应该尽我们最大的努力减少塑料包装的使用，并回收所有的塑料废物。","targetForm":"recycle","senseId":"source-v-1","sourceSenseId":"v-1"}]},"remember":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"铭记"},{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"记得"}],"examples":[{"sentence":"It is for this indispensable quality of statesmanship, not only for having helped bring about German reunification, that Kohl deserves to be remembered and mourned.","translation":"正是这种不可或缺的政治家的品质，而不仅仅是因为带来了德国的重新统一，让科尔值得被铭记和哀悼。","targetForm":"remembered","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"As the world watches Libya’s Muammar el-Qaddafi slaughter his own people, we should remember the human cost of international indifference.","translation":"在世界目睹利比亚的穆阿迈尔·卡扎菲屠杀国内民众的时候，我们不应该忘记国际冷漠所造成的人道主义损失。","targetForm":"remember","senseId":"source-v-1","sourceSenseId":"v-1"}]},"retain":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"留住"}],"examples":[{"sentence":"This will require infrastructure development, as well as reliable systems for procuring supplies, maintaining equipment, and training and retaining personnel.","translation":"监控严重耐药型结核病的重点包括鼓励进行对二线药物的可靠的敏感性测试，并将相关信息与艾滋病测试信息一起，纳入现有的结核病监控计划之中。","targetForm":"retaining","senseId":"source-v-3","sourceSenseId":"v-3"}]},"relativity":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"相对性"}],"examples":[{"sentence":"We associate the name of Einstein with the theory of relativity.","translation":"一提到爱因斯坦，我们就会想起相对论。","targetForm":"relativity","senseId":"source-n-3","sourceSenseId":"n-3"}]},"repair":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"修复"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"修理"}],"examples":[{"sentence":"In these circumstances, we need collective action for global recovery along four main policy lines: repair, reform, rebalancing, and rebuilding.","translation":"在这样的情况下，我们需要集体行动来提振全球复苏，主要包括四条政策路线：修复、改革、再平衡和重建。","targetForm":"repair","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"I will only buy the car if they repair the brakes first.","translation":"除非他们事先修好刹车，我才会买车子。","targetForm":"repair","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The repairs cost a lot more than 15 dollars, of course, but I am grateful to them for finding a solution.","translation":"理所当然，修理费用比15元还要多更多，但是我非常感激他们找到了解决的办法。","targetForm":"repairs","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"This TV was made ten years ago and there are no parts available, so it is impossible to repair it.","translation":"这台电视机是十年前制造的, 现在已经没有零件可换, 所以要修理它是不可能的事了。","targetForm":"repair","senseId":"source-n-1","sourceSenseId":"n-1"}]},"register":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"登记簿"},{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"注册"}],"examples":[{"sentence":"No person by that name is listed in the register of the school.","translation":"学校的名册里没有这个名字的人。","targetForm":"register","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"Sir, please present your passport or identity card, so I can register it.","translation":"先生，请出示护照或者身份证，让我登记一下。","targetForm":"register","senseId":"source-n-4","sourceSenseId":"n-4"}]},"repertoire":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"全部作品"}],"examples":[{"sentence":"Her repertoire on the piano is not very large, but she has learned every piece by heart.","translation":"虽然在钢琴上她的造诣不是很深，但是她勤而好学。","targetForm":"repertoire","senseId":"source-n-4","sourceSenseId":"n-4"}]},"reserve":{"senseGroups":[{"id":"source-n-8","partOfSpeech":"n.","sourceSenseIds":["n-8"],"sense":"储备金"}],"examples":[{"sentence":"History suggests that collective negotiation about currencies and a new approach to the issue of reserves are unlikely to succeed.","translation":"历史似乎意味着，有关汇率和储备问题新方案的会谈是不太可能成功的。","targetForm":"reserves","senseId":"source-n-8","sourceSenseId":"n-8"},{"sentence":"As US Federal Reserve Chairman Ben Bernanke has argued, trade expansion inevitably creates some losers, whose protests distract attention from the benefits of globalization.","translation":"这个观点是正确的，但是，它只是事情的一部分，因为它忽略了在关键时刻，自由贸易是怎样获得众多胜利者的支持的。","targetForm":"reserve","senseId":"source-n-8","sourceSenseId":"n-8"},{"sentence":"Finally, some object that bankers dominate the boards of directors of the regional Reserve Banks, making it seem that the foxes are guarding the henhouse.","translation":"最后，一些人反对银行家把持了地区联储银行董事会，这就好像是让狐狸看守鸡窝。","targetForm":"reserve","senseId":"source-n-8","sourceSenseId":"n-8"}]},"resemblance":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"相似处"}],"examples":[{"sentence":"No matter how close the resemblance, there's always a difference.","translation":"事物无论多相似还是会有点差异的。","targetForm":"resemblance","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"I was surprised at his strong resemblance to his father.","translation":"他像极了他父亲，这让我震惊。","targetForm":"resemblance","senseId":"source-n-1","sourceSenseId":"n-1"}]},"revelation":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"揭露"}],"examples":[{"sentence":"But the most shocking revelation may be this: the Saudis knew they could get away with murder.","translation":"但最令人震惊的启示可能是这一点：沙特人知道自己可以摆脱谋杀指控。","targetForm":"revelation","senseId":"source-n-1","sourceSenseId":"n-1"}]},"repeatedly":{"senseGroups":[{"id":"source-adv-1","partOfSpeech":"adv.","sourceSenseIds":["adv-1"],"sense":"重复地"},{"id":"source-adv-2","partOfSpeech":"adv.","sourceSenseIds":["adv-2"],"sense":"再三地"}],"examples":[{"sentence":"Dear Germany: Sorry that Trump has repeatedly insulted Chancellor Angela Merkel.","translation":"亲爱的德国：对不起，特朗普 多次攻击你们的总理默克尔。","targetForm":"repeatedly","senseId":"source-adv-1","sourceSenseId":"adv-1"},{"sentence":"I can't believe you are eating something the doctor has told you repeatedly you shouldn't eat.","translation":"真的不敢相信你在吃医生叮嘱不要食用的东西。","targetForm":"repeatedly","senseId":"source-adv-2","sourceSenseId":"adv-2"},{"sentence":"I'm tossing and turning, repeatedly thinking about what happened today, deeply remorseful.","translation":"我辗转反侧，反复思考着白天发生的事，后悔不已。","targetForm":"repeatedly","senseId":"source-adv-1","sourceSenseId":"adv-1"}]},"ready":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"预备好的状态"}],"examples":[{"sentence":"Since all tasks have been completed without delay, we are ready to start the next phase of development.","translation":"既然所有的任务都按时完成了，我们已经准备好开始下一阶段的开发了。","targetForm":"ready","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"When real life friends desert us, books are always ready to offer friendship, sympathy and motivation.","translation":"生活中的朋友弃我们不顾之时，书随时给我们送来友谊、同情和鼓励。","targetForm":"ready","senseId":"source-n-1","sourceSenseId":"n-1"}]},"receipt":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"收据"}],"examples":[{"sentence":"I lost my receipt and had to call customer service at both IKEA and the bank.","translation":"我遗失了收据，不得不给 IKEA 和银行的客服部门打电话。","targetForm":"receipt","senseId":"source-n-1","sourceSenseId":"n-1"}]},"refresh":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"提起精神"},{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"使恢复"}],"examples":[{"sentence":"A glass of cold water is very refreshing in hot weather.","translation":"一杯冷水在暑热的天气里十分提神。","targetForm":"refreshing","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"So wine and venison, to their hearts' desire, / refreshed their strength.","translation":"于是，他们心满意足地享用了美酒和野味，/ 恢复了体力。","targetForm":"refreshed","senseId":"source-v-2","sourceSenseId":"v-2"}]},"revenue":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"岁入"}],"examples":[{"sentence":"In comparison, shale gas in the US has created an estimated 600,000 jobs that are generating about $100 billion in added GDP and almost $20 billion in public revenue.","translation":"比较而言，页岩气在美国创造了约60万个就业岗位、增加了1000亿美元的GDP和近200亿美元的公共收入。","targetForm":"revenue","senseId":"source-n-2","sourceSenseId":"n-2"}]},"restore":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"恢复"}],"examples":[{"sentence":"Another powerful measure would be to protect and restore natural ecosystems, which could result in the storage of 220-330 gigatons of CO2 worldwide .","translation":"另一项强力措施是保护和重建自然生态系统，这样可以储存2,200—3,300亿吨二氧化碳。","targetForm":"restore","senseId":"source-v-2","sourceSenseId":"v-2"}]},"residence":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"居留"},{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"住宅"}],"examples":[{"sentence":"Everyone has the right to freedom of movement and residence within the borders of each State.","translation":"每个人在各国境内均享有迁徙自由与居住自由的权利。","targetForm":"residence","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"In Beijing, hutongs are alleys formed by lines of siheyuans, the traditional courtyard residences.","translation":"在北京，胡同是由四合院的传统居所排形成。","targetForm":"residences","senseId":"source-n-1","sourceSenseId":"n-1"}]},"reap":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"获得"}],"examples":[{"sentence":"The Palestinian side, for its part, must accept that Israel is here to stay, and that huge benefits can be reaped from economic cooperation.","translation":"在巴勒斯坦方，必须接受以色列已在这里定居的现实，并意识到经济合作可以带来巨大的好处。","targetForm":"reaped","senseId":"source-v-3","sourceSenseId":"v-3"}]},"rest":{"senseGroups":[{"id":"source-n-6","partOfSpeech":"n.","sourceSenseIds":["n-6"],"sense":"支架"},{"id":"source-n-8","partOfSpeech":"n.","sourceSenseIds":["n-8"],"sense":"其余者"}],"examples":[{"sentence":"To meet this challenge, we have designed an economic strategy that rests on three pillars: Europe, fiscal consolidation, and competitiveness.","translation":"为了面对这一挑战，我们设计了基于三大基石的经济战略：欧洲、财政整合和竞争力。","targetForm":"rests","senseId":"source-n-6","sourceSenseId":"n-6"},{"sentence":"In a developed-country setting, the reality is that going entirely vegetarian for the rest of your life means reducing your emissions by about 2%.","translation":"在发达国家条件下，现实是余生完全吃素可以让你的排放减少大约2 % 。","targetForm":"rest","senseId":"source-n-8","sourceSenseId":"n-8"}]},"resist":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"抵抗"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"抵制"}],"examples":[{"sentence":"It was the response thrown back at those who wanted the US to resist Hitler’s Germany.","translation":"这是对希望美国抵抗希特勒德国的人所得到的回应。","targetForm":"resist","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"There are at least three reasons why the IMF should resist this pressure, and abstain from increasing its (already extremely high) exposure to Europe.","translation":"IMF至少有三大理由抵制这一要求，并拒绝增加其（已然极高的）对欧洲的风险暴露。","targetForm":"resist","senseId":"source-v-3","sourceSenseId":"v-3"}]},"recorder":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"录音机"}],"examples":[{"sentence":"I got a video cassette recorder cheap at that shop.","translation":"我在那商店花低价买了台录像机。","targetForm":"recorder","senseId":"source-n-2","sourceSenseId":"n-2"}]},"readily":{"senseGroups":[{"id":"source-adv-3","partOfSpeech":"adv.","sourceSenseIds":["adv-3"],"sense":"乐意地"},{"id":"source-adv-2","partOfSpeech":"adv.","sourceSenseIds":["adv-2"],"sense":"轻易地"}],"examples":[{"sentence":"People will accept your idea much more readily if you tell them Benjamin Franklin said it first.","translation":"如果你告诉他们富兰克林是第一个这么说的, 人们会更乐意接受你的想法。","targetForm":"readily","senseId":"source-adv-3","sourceSenseId":"adv-3"},{"sentence":"We all know that blue-eyed red-heads are sensitive to sunshine, burning more readily than dark-skinned people.","translation":"我们都知道，蓝眼睛红头发的人对阳光敏感，比深色皮肤的人更容易晒伤。","targetForm":"readily","senseId":"source-adv-2","sourceSenseId":"adv-2"},{"sentence":"Although Hiroko dislikes cigarette smoke, she readily goes out drinking with friends.","translation":"虽然弘子不喜欢香烟的烟雾，她却乐意和朋友出去喝酒。","targetForm":"readily","senseId":"source-adv-3","sourceSenseId":"adv-3"}]},"relieve":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"减轻"}],"examples":[{"sentence":"I felt quite relieved after I had said all I wanted to say.","translation":"说了所有我要说的话后，我感觉很轻松。","targetForm":"relieved","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"When you're about to have exams, lifting weights really does relieve stress, and it's also good for your mind and body.","translation":"快要考试的时候，举重真的消愁解闷，再说对身体和精神都很好。","targetForm":"relieve","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"After you take the medicine, your stomachache will be much relieved.","translation":"你吃了这药，胃痛就会缓解很多。","targetForm":"relieved","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"We felt relieved when we saw a light in the distance.","translation":"我们看见远处传来了一点光，不禁都松了一口气。","targetForm":"relieved","senseId":"source-v-1","sourceSenseId":"v-1"}]},"refine":{"senseGroups":[{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"使优雅"}],"examples":[{"sentence":"The cat glided along, very refined, but ended up falling, which was very embarrassing.","translation":"这只猫咪气场全开，走着猫步，相当优雅，然后摔倒了，真是糗大了。","targetForm":"refined","senseId":"source-v-3","sourceSenseId":"v-3"}]},"republican":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"共和党员"}],"examples":[{"sentence":"When reasonable Republicans and Democrats begin to converge on policy, we are more likely to get sensible change.","translation":"当理性的共和党和民主党人开始在政策上趋同时，我们就更有可能实现合理的变革。","targetForm":"republicans","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"Meanwhile, House Republicans are preparing their own Fed governance reforms, which would be even more radical – and would likely constrain monetary policy unwisely.","translation":"与此同时，众议院正在准备其自身的美联储治理改革方案 — — 这一方案将更加激进，有可能不明智地约束货币政策。","targetForm":"republicans","senseId":"source-n-2","sourceSenseId":"n-2"},{"sentence":"CAMBRIDGE – In the French Republican party’s presidential primary on Sunday, François Fillon soundly defeated frontrunner Alain Juppé, winning close to 67% of the votes.","translation":"剑桥 — — 在星期天进行的法国共和党总统初选中，弗朗索瓦·菲永以赢得67%选票的成绩毫无争议地击败了领跑者阿兰·朱佩。","targetForm":"republican","senseId":"source-n-2","sourceSenseId":"n-2"}]},"realise":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"认识到"}],"examples":[{"sentence":"Do not wait until everyone says that you are ugly before realising that you really are ugly.","translation":"不要等到人人都说你丑时才发现自己真的丑。","targetForm":"realising","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"I never know what to say to people who have absolutely no grasp of the basic facts and are too ignorant to realise it.","translation":"对于那些连基本事实都搞不清楚而且又盲目得无法了解到这一点的人，我从来都不知道对他们说些什么。","targetForm":"realise","senseId":"source-v-2","sourceSenseId":"v-2"}]},"restrict":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"限制"}],"examples":[{"sentence":"While video platforms do not explicitly ban such content, works of this type will have their traffic restricted.","translation":"虽然视频平台没有明确禁止此类内容，但这种类型的作品的流量会被限制。","targetForm":"restricted","senseId":"source-v-1","sourceSenseId":"v-1"}]},"reader":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"读者"}],"examples":[{"sentence":"Readers of their argument may want to consider the following points.","translation":"读了他们的观点的读者可能会考虑以下几点。","targetForm":"readers","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Just because a certain book does not interest readers does not mean that the fault lies in the book.","translation":"不是因为读者对某本书不感兴趣，这本书就肯定是有问题的了。","targetForm":"readers","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"Writer Luiz Fernando Veríssimo, a columnist capable of uniting generations of readers with irony, precision and sensitivity, died in Porto Alegre, Brazil.","translation":"作家路易斯・费尔南多・沃瑞西莫在巴西阿雷格里港去世，他是位专栏作家，能以讽刺、精确、敏感的文笔团结几代读者。","targetForm":"readers","senseId":"source-n-1","sourceSenseId":"n-1"}]},"resident":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"居民"}],"examples":[{"sentence":"The residents protested outside the sex shop that opened in their neighborhood recently.","translation":"居民们在一家开在邻近的性用品商店前抗议。","targetForm":"residents","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The implication was that where there was a well, there were residents.","translation":"含义是哪里有水井，哪里就有居民。","targetForm":"residents","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"The school's lovely cherry blossoms drew a lot of residents to come and admire it.","translation":"学校的樱花开的烂漫，吸引了大量市民前来观赏。","targetForm":"residents","senseId":"source-n-1","sourceSenseId":"n-1"},{"sentence":"More than half of the residents are opposed to the plan.","translation":"有过半数的居民反对这个计划。","targetForm":"residents","senseId":"source-n-1","sourceSenseId":"n-1"}]},"recreation":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"休息"},{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"消遣"}],"examples":[{"sentence":"People who cannot find time for recreation are obliged sooner or later to find time for illness.","translation":"没工夫休息的人，早晚会有工夫生病的。","targetForm":"recreation","senseId":"source-n-3","sourceSenseId":"n-3"},{"sentence":"The city of Toronto has about 160 community recreation centres, many of which include swimming pools, skating and curling rinks, gymnasiums, weight rooms and meeting rooms.","translation":"多伦多市拥有约 160 个社区休闲中心，其中许多设有游泳池、溜冰及冰壶场、体育馆、健身房，以及会议室。","targetForm":"recreation","senseId":"source-n-2","sourceSenseId":"n-2"}]},"require":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"需要"}],"examples":[{"sentence":"That our profligate consumption requires five planets is a catchy story, but it is wrong.","translation":"比约恩·隆姆博格，哥本哈根共识中心的主任，是哥本哈根商学院兼职教授，着有《怀疑主义环保分子并请冷静：怀疑主义环保分子之全球变暖指南 》 。","targetForm":"requires","senseId":"source-v-1","sourceSenseId":"v-1"}]},"remedy":{"senseGroups":[{"id":"source-n-4","partOfSpeech":"n.","sourceSenseIds":["n-4"],"sense":"补救"}],"examples":[{"sentence":"So here, too, the logic points to a vicious circle: Slower growth leads to artificial remedies and further erosion of long-term growth potential.","translation":"这一解释的逻辑也指向一个恶性循环：增长减速导致伪方案，从而进一步破坏长期增长潜力。","targetForm":"remedies","senseId":"source-n-4","sourceSenseId":"n-4"}]},"remove":{"senseGroups":[{"id":"source-v-1","partOfSpeech":"v.","sourceSenseIds":["v-1"],"sense":"移动"},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"除去"}],"examples":[{"sentence":"The implication is clear: although Europe has made significant progress toward fiscal union, it remains far removed from political union.","translation":"影响显而易见：尽管欧洲朝着财政联盟的方向取得了重大进步，但距离政治联盟依然十分遥远。","targetForm":"removed","senseId":"source-v-1","sourceSenseId":"v-1"},{"sentence":"And oh, yes, it would be helpful if the world’s greatest philanthropist were to throw his weight behind removing the stigma on DDT.","translation":"哦还有，如果全世界最伟大的慈善家能施展影响力为DDT正名就更好了。","targetForm":"removing","senseId":"source-v-3","sourceSenseId":"v-3"},{"sentence":"Use interrogative pronouns to rewrite the sentences below; if you need to, you can add or remove a few words.","translation":"用疑问代词表任指格式改写下面的句子，根据需要可以增加或者减少一些词语。","targetForm":"remove","senseId":"source-v-3","sourceSenseId":"v-3"}]},"regard":{"senseGroups":[{"id":"source-n-2","partOfSpeech":"n.","sourceSenseIds":["n-2"],"sense":"注意"}],"examples":[{"sentence":"Islamic fundamentalists reckon that what the rest of us regard as the liberalizing influence of technological progress and globalization is a brash re-run of Western colonialism.","translation":"以色列原教旨主义者认为我们其他人眼中技术进步和全球化的自由化影响反应出西方殖民主义不可一世的重新抬头。","targetForm":"regard","senseId":"source-n-2","sourceSenseId":"n-2"}]},"refer":{"senseGroups":[{"id":"source-v-4","partOfSpeech":"v.","sourceSenseIds":["v-4"],"sense":"使求助于"},{"id":"source-v-5","partOfSpeech":"v.","sourceSenseIds":["v-5"],"sense":"提到"},{"id":"source-v-7","partOfSpeech":"v.","sourceSenseIds":["v-7"],"sense":"查阅"}],"examples":[{"sentence":"I am happy to refer those seeking further particulars to one such former practicing physician: my wife.","translation":"我很高兴地推荐一位曾经使用这类系统的执业医师给那些希望进一步了解这些问题的人：我的夫人。","targetForm":"refer","senseId":"source-v-4","sourceSenseId":"v-4"},{"sentence":"There are only two ways, I believe, for the world to avoid what most scientists refer to as disastrous global warming.","translation":"我认为，只有两个办法可以让世界摆脱大部分科学家所谓的灾难性全球变暖。","targetForm":"refer","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"While in England, I often referred to the guidebook for details of my journey.","translation":"我在英国的时候，经常翻阅旅游指南，查询旅途中的相关细节。","targetForm":"referred","senseId":"source-v-7","sourceSenseId":"v-7"},{"sentence":"Celebrating Spring Festival is commonly referred to as 'passing the year'.","translation":"庆祝春节俗称过年。","targetForm":"referred","senseId":"source-v-5","sourceSenseId":"v-5"},{"sentence":"Standard Chinese, commonly referred to as Mandarin, is based on Pekinese.","translation":"中文的标准语，也就是人们常说的普通话，以北京口音为基础。","targetForm":"referred","senseId":"source-v-5","sourceSenseId":"v-5"}]},"recipe":{"senseGroups":[{"id":"source-n-3","partOfSpeech":"n.","sourceSenseIds":["n-3"],"sense":"秘诀"}],"examples":[{"sentence":"The frog and I took turns guessing what the secret recipe was.","translation":"青蛙和我轮流猜了秘方是什么。","targetForm":"recipe","senseId":"source-n-3","sourceSenseId":"n-3"}]},"regime":{"senseGroups":[{"id":"source-n-1","partOfSpeech":"n.","sourceSenseIds":["n-1"],"sense":"政权"}],"examples":[{"sentence":"Europe’s policy for Iran is not regime change, but when human rights and democracy are at stake, we cannot simply close our eyes.","translation":"欧洲对伊朗的政策不是实现政权更替，但当人权和民主告急之时，我们可不能无动于衷，袖手旁观。","targetForm":"regime","senseId":"source-n-1","sourceSenseId":"n-1"}]},"renew":{"senseGroups":[{"id":"source-v-2","partOfSpeech":"v.","sourceSenseIds":["v-2"],"sense":"使恢复"},{"id":"source-v-8","partOfSpeech":"v.","sourceSenseIds":["v-8"],"sense":"重申"}],"examples":[{"sentence":"So, while this latest bear-market rally may continue for a bit longer, renewed downward pressure on stocks and other risky assets is inevitable.","translation":"因此，尽管最近这次熊市反弹将持续更长时间，但股票和其他风险性资产必将重新感受到向下的压力。","targetForm":"renewed","senseId":"source-v-2","sourceSenseId":"v-2"},{"sentence":"Next month is their 50th anniversary, and they're planning on renewing their vows.","translation":"下个月是他们的五十周年纪念，他们打算重新宣誓。","targetForm":"renewing","senseId":"source-v-8","sourceSenseId":"v-8"}]},"recommend":{"senseGroups":[{"id":"source-v-6","partOfSpeech":"v.","sourceSenseIds":["v-6"],"sense":"[经] 建议","contextReviewed":true},{"id":"source-v-3","partOfSpeech":"v.","sourceSenseIds":["v-3"],"sense":"劝告"}],"examples":[{"sentence":"Instead, the panel recommended focusing investment on research into climate engineering as a short-term response, and on non-carbon-based energy as a longer-term response.","translation":"相反，专家组建议将投资重点放在气候工程研究��以作为短期的应对措施，并将无碳基能源的研究来作为长期应对措施。","targetForm":"recommended","senseId":"source-v-6","sourceSenseId":"v-6"},{"sentence":"The weak point of this book is that it's less than persuasive when the married author recommends not being married.","translation":"这本书有一个弱点 ﹣ 作者自己结了婚，但却建议别人不要结婚，没有甚么说服力。","targetForm":"recommends","senseId":"source-v-3","sourceSenseId":"v-3"}]}}};
